39	/* ========== UI状态枚举 ========== */
40	typedef enum {
41	    TONG_STATE_IDLE = 0,        /**< 待命，显示问候语 */
42	    TONG_STATE_CONNECTING,      /**< 正在连接服务器 */
43	    TONG_STATE_CONNECTED,       /**< 已连接，等待说话 */
44	    TONG_STATE_LISTENING,       /**< 用户正在说话(服务端VAD) */
45	    TONG_STATE_THINKING,       /**< 用户说完了，等待AI回复 */
46	    TONG_STATE_SPEAKING,       /**< 正在播放AI回复 */
47	    TONG_STATE_ERROR            /**< 连接错误 */
48	} tong_ui_state_t;
