137	/**
138	 * @brief 更新笑脸表情
139	 * @param mouth_type 0=微笑, 1=中性, 2=难过
140	 */
141	static void tong_update_face_emotion(int mouth_type)
142	{
143	    if (!tong_face_mouth) return;
144	
145	    static const lv_point_precise_t smile_pts[] = {
146	        {30, 72}, {40, 78}, {50, 82}, {60, 84}, {70, 82}, {80, 78}, {90, 72}
147	    };
148	    static const lv_point_precise_t neutral_pts[] = {
149	        {35, 80}, {50, 80}, {60, 80}, {70, 80}, {85, 80}
150	    };
151	    static const lv_point_precise_t frown_pts[] = {
152	        {30, 84}, {40, 78}, {50, 74}, {60, 72}, {70, 74}, {80, 78}, {90, 84}
153	    };
154	
155	    const lv_point_precise_t *pts;
156	    uint32_t pt_count;
157	
158	    switch (mouth_type) {
159	    case 0: /* 微笑 */
160	        pts = smile_pts;
161	        pt_count = sizeof(smile_pts) / sizeof(smile_pts[0]);
162	        break;
163	    case 1: /* 中性(连接中等候) */
164	        pts = neutral_pts;
165	        pt_count = sizeof(neutral_pts) / sizeof(neutral_pts[0]);
166	        break;
167	    case 2: /* 难过(错误) */
168	        pts = frown_pts;
169	        pt_count = sizeof(frown_pts) / sizeof(frown_pts[0]);
170	        break;
171	    default:
172	        pts = smile_pts;
173	        pt_count = sizeof(smile_pts) / sizeof(smile_pts[0]);
174	        break;
175	    }
176	
177	    lv_line_set_points(tong_face_mouth, pts, pt_count);
178	}
