180	/* ========== 状态更新 ========== */
181	
182	static void tong_update_ui_state(tong_ui_state_t state, const char *error_msg)
183	{
184	    g_tong_state = state;
185	
186	    if (!tong_main_base) return;
187	
188	    switch (state) {
189	    case TONG_STATE_IDLE:
190	        if (tong_title_label)
191	            lv_label_set_text(tong_title_label, "待命");
192	        if (tong_face_container) {
193	            lv_obj_clear_flag(tong_face_container, LV_OBJ_FLAG_HIDDEN);
194	            tong_update_face_emotion(0);
195	        }
196	        if (tong_status_label) {
197	            lv_label_set_text(tong_status_label, "Hi! 有什么可以帮到你呢？");
198	            lv_obj_clear_flag(tong_status_label, LV_OBJ_FLAG_HIDDEN);
199	        }
200	        if (tong_status_sub_label)
201	            lv_label_set_text(tong_status_sub_label, "");
202	        if (tong_action_btn_label)
203	            lv_label_set_text(tong_action_btn_label, "开始对话");
204	        break;
205	
206	    case TONG_STATE_CONNECTING:
207	        if (tong_title_label)
208	            lv_label_set_text(tong_title_label, "连接中...");
209	        if (tong_face_container) {
210	            lv_obj_clear_flag(tong_face_container, LV_OBJ_FLAG_HIDDEN);
211	            tong_update_face_emotion(1);
212	        }
213	        if (tong_status_label) {
214	            lv_label_set_text(tong_status_label, "正在连接服务器...");
215	            lv_obj_clear_flag(tong_status_label, LV_OBJ_FLAG_HIDDEN);
216	        }
217	        if (tong_status_sub_label)
218	            lv_label_set_text(tong_status_sub_label, "");
219	        if (tong_action_btn_label)
220	            lv_label_set_text(tong_action_btn_label, "取消");
221	        break;
222	
223	    case TONG_STATE_CONNECTED:
224	        if (tong_title_label)
225	            lv_label_set_text(tong_title_label, "小通AI");
226	        if (tong_face_container) {
227	            lv_obj_clear_flag(tong_face_container, LV_OBJ_FLAG_HIDDEN);
228	            tong_update_face_emotion(0);
229	        }
230	        if (tong_status_label) {
231	            lv_label_set_text(tong_status_label, "小通已就绪");
232	            lv_obj_clear_flag(tong_status_label, LV_OBJ_FLAG_HIDDEN);
233	        }
234	        if (tong_status_sub_label)
235	            lv_label_set_text(tong_status_sub_label, "可以直接说话");
236	        if (tong_action_btn_label)
237	            lv_label_set_text(tong_action_btn_label, "结束对话");
238	        break;
239	
240	    case TONG_STATE_LISTENING:
241	        if (tong_title_label)
242	            lv_label_set_text(tong_title_label, "聆听中");
243	        if (tong_face_container) {
244	            lv_obj_clear_flag(tong_face_container, LV_OBJ_FLAG_HIDDEN);
245	            tong_update_face_emotion(1);
246	        }
247	        if (tong_status_label) {
248	            lv_label_set_text(tong_status_label, "正在聆听...");
249	            lv_obj_clear_flag(tong_status_label, LV_OBJ_FLAG_HIDDEN);
250	        }
251	        if (tong_status_sub_label)
252	            lv_label_set_text(tong_status_sub_label, "");
253	        if (tong_action_btn_label)
254	            lv_label_set_text(tong_action_btn_label, "结束对话");
255	        break;
256	
257	    case TONG_STATE_THINKING:
258	        if (tong_title_label)
259	            lv_label_set_text(tong_title_label, "思考中");
260	        if (tong_face_container) {
261	            lv_obj_clear_flag(tong_face_container, LV_OBJ_FLAG_HIDDEN);
262	            tong_update_face_emotion(1);
263	        }
264	        if (tong_status_label) {
265	            lv_label_set_text(tong_status_label, "小通正在思考...");
266	            lv_obj_clear_flag(tong_status_label, LV_OBJ_FLAG_HIDDEN);
267	        }
268	        if (tong_status_sub_label)
269	            lv_label_set_text(tong_status_sub_label, "");
270	        if (tong_action_btn_label)
271	            lv_label_set_text(tong_action_btn_label, "结束对话");
272	        break;
273	
274	    case TONG_STATE_SPEAKING:
275	        if (tong_title_label)
276	            lv_label_set_text(tong_title_label, "回复中");
277	        if (tong_face_container) {
278	            lv_obj_clear_flag(tong_face_container, LV_OBJ_FLAG_HIDDEN);
279	            tong_update_face_emotion(0);
280	        }
281	        if (tong_status_label) {
282	            lv_label_set_text(tong_status_label, "小通正在回复...");
283	            lv_obj_clear_flag(tong_status_label, LV_OBJ_FLAG_HIDDEN);
284	        }
285	        if (tong_status_sub_label)
286	            lv_label_set_text(tong_status_sub_label, "");
287	        if (tong_action_btn_label)
288	            lv_label_set_text(tong_action_btn_label, "打断");
289	        break;
290	
291	    case TONG_STATE_ERROR:
292	        if (tong_title_label)
293	            lv_label_set_text(tong_title_label, "连接失败");
294	        if (tong_face_container) {
295	            lv_obj_clear_flag(tong_face_container, LV_OBJ_FLAG_HIDDEN);
296	            tong_update_face_emotion(2);
297	        }
298	        if (tong_status_label) {
299	            if (error_msg && error_msg[0]) {
300	                lv_label_set_text(tong_status_label, error_msg);
301	            } else {
302	                lv_label_set_text(tong_status_label, "连接失败，请重试");
303	            }
304	            lv_obj_clear_flag(tong_status_label, LV_OBJ_FLAG_HIDDEN);
305	        }
306	        if (tong_status_sub_label) {
307	            lv_label_set_text(tong_status_sub_label, "请检查网络连接后重试");
308	        }
309	        if (tong_action_btn_label)
310	            lv_label_set_text(tong_action_btn_label, "重试");
311	        break;
312	    }
313	}
