315	/* ========== ASR发音变体匹配（复用tong_ai_ws.c中的数组，避免DRAM重复） ========== */
316	
317	extern const char * const VAR_CHAOWAN[];
318	extern const char * const VAR_BIAOQING[];
319	extern const char * const VAR_BIOPAN[];
320	
321	static int strstr_any(const char *buf, const char * const variants[])
322	{
323	    for (int i = 0; variants[i] != NULL; i++) {
324	        if (strstr(buf, variants[i])) return 1;
325	    }
326	    return 0;
327	}
