329	/* ========== volc事件回调 (从recv_thread/start_thread调用) ========== */
330	
331	static void volc_event_callback(volc_callback_type_t type, const char *data)
332	{
333	    switch (type) {
334	    case VOLC_CB_UI_STATE:
335	        if (data) {
336	            g_pending_volc_state = (volc_ui_state_t)(unsigned char)data[0];
337	            g_pending_flags |= PENDING_STATE;
338	        }
339	        break;
340	    case VOLC_CB_ERROR_MSG:
341	        if (data && g_pending_error_msg) {
342	            strncpy(g_pending_error_msg, data, PENDING_ERROR_MSG_SIZE - 1);
343	            g_pending_error_msg[PENDING_ERROR_MSG_SIZE - 1] = '\0';
344	            g_pending_flags |= PENDING_ERROR;
345	        }
346	        break;
347	    case VOLC_CB_CONNECTED:
348	        /* 由 VOLC_CB_UI_STATE(VOLC_UI_CONNECTED) 处理 */
349	        break;
350	    case VOLC_CB_USER_TEXT:
351	        if (data) {
352	            syslog(LOG_INFO, "[TONG] ASR: \"%s\"\n", data);
353	
354	            /* 智能家居指令检测（优先于UI模式切换） */
355	            int hc_ret = home_control_voice_execute(data);
356	            if (hc_ret == HOME_CTRL_NET_FAIL) {
357	                /* 匹配到设备但网络失败 */
358	                syslog(LOG_INFO,
359	                    "[TONG] home ctrl net fail: \"%s\"\n", data);
360	                volc_play_local_wav(HOME_CTRL_FAIL_WAV);
361	                break;
362	            } else if (hc_ret == HOME_CTRL_NO_MATCH) {
363	                /* 有开关动作词但未匹配到设备 */
364	                syslog(LOG_INFO,
365	                    "[TONG] home ctrl no match: \"%s\"\n", data);
366	                volc_play_local_wav(HOME_CTRL_NOT_FOUND_WAV);
367	                break;
368	            }
369	            /* HOME_CTRL_OK: 指令成功，继续正常流程
370	             * HOME_CTRL_NONE: 无关指令，继续UI模式切换检测 */
371	
372	            int matched = 0;
373	            /* 策略1: 完整短语匹配（含发音变体） */
374	            if (strstr_any(data, VAR_CHAOWAN) ||
375	                strstr_any(data, VAR_BIAOQING)) {
376	                matched = 1;
377	            }
378	            /* 策略2: 动作词+目标词变体组合匹配 */
379	            if (!matched) {
380	                int has_action = (strstr(data, "切换") ||
381	                    strstr(data, "打开") ||
382	                    strstr(data, "进入") ||
383	                    strstr(data, "回到") ||
384	                    strstr(data, "返回"));
385	                int has_target = (strstr_any(data, VAR_CHAOWAN) ||
386	                    strstr_any(data, VAR_BIAOQING) ||
387	                    strstr_any(data, VAR_BIOPAN));
388	                if (has_action && has_target) matched = 1;
389	            }
390	            if (matched) {
391	                syslog(LOG_INFO, "[TONG] UI mode switch triggered: %s\n", data);
392	                FILE *fp = fopen("/mnt/spif/ui_mode.json", "w");
393	                if (fp) {
394	                    fprintf(fp, "{\"ui_mode\":0}\n");
395	                    fclose(fp);
396	                }
397	                axp2101_power_reset();
398	                /* 不会到达这里 */
399	            }
400	        }
401	        break;
402	    case VOLC_CB_DISCONNECTED:
403	        g_pending_flags |= PENDING_DISCONNECTED;
404	        break;
405	    }
406	}
