408	/* ========== LVGL定时器 — 处理pending事件 ========== */
409	
410	static void volc_timer_cb(lv_timer_t *timer)
411	{
412	    (void)timer;
413	
414	    /* 取出所有pending标志(原子性读取) */
415	    uint8_t flags = g_pending_flags;
416	    g_pending_flags = 0;
417	
418	    if (flags & PENDING_STATE) {
419	        tong_ui_state_t ui_state;
420	        switch (g_pending_volc_state) {
421	        case VOLC_UI_IDLE:          ui_state = TONG_STATE_IDLE; break;
422	        case VOLC_UI_CONNECTING:   ui_state = TONG_STATE_CONNECTING; break;
423	        case VOLC_UI_CONNECTED:    ui_state = TONG_STATE_CONNECTED; break;
424	        case VOLC_UI_LISTENING:    ui_state = TONG_STATE_LISTENING; break;
425	        case VOLC_UI_THINKING:     ui_state = TONG_STATE_THINKING; break;
426	        case VOLC_UI_SPEAKING:     ui_state = TONG_STATE_SPEAKING; break;
427	        case VOLC_UI_DISCONNECTING: ui_state = TONG_STATE_IDLE; break;
428	        case VOLC_UI_ERROR:        ui_state = TONG_STATE_ERROR; break;
429	        default:                   ui_state = TONG_STATE_IDLE; break;
430	        }
431	        tong_update_ui_state(ui_state, NULL);
432	    }
433	
434	    if (flags & PENDING_ERROR)
435	        tong_update_ui_state(TONG_STATE_ERROR, g_pending_error_msg);
436	
437	    if (flags & PENDING_DISCONNECTED)
438	        tong_update_ui_state(TONG_STATE_IDLE, NULL);
439	
440	    /* 检查启动线程状态 */
441	    if (!g_starting && g_cancel_requested) {
442	        g_cancel_requested = false;
443	        if (g_start_ret == 0) {
444	            /* 启动成功但用户已取消，需要停止 */
445	            volc_voice_stop();
446	        }
447	        tong_update_ui_state(TONG_STATE_IDLE, NULL);
448	    }
449	}
