451	/* ========== 启动线程 (避免阻塞LVGL) ========== */
452	
453	#define START_THREAD_STACK (32 * 1024)
454	
455	static void *voice_start_thread(void *arg)
456	{
457	    (void)arg;
458	    TONG_LOG("[TONG] voice_start_thread begin\n");
459	    g_start_ret = volc_voice_start(volc_event_callback);
460	    TONG_LOG("[TONG] voice_start_thread ret=%d\n", g_start_ret);
461	
462	    if (g_cancel_requested) {
463	        if (g_start_ret == 0) {
464	            /* 启动成功但用户已取消 */
465	            volc_voice_stop();
466	        }
467	        /* 启动失败的清理由volc模块内部完成 */
468	    }
469	    /* 成功时：回调会通过pending标志驱动UI到CONNECTED状态 */
470	
471	    g_starting = false;
472	    return NULL;
473	}
