475	/* ========== 按钮事件处理 ========== */
476	
477	static void action_btn_click_handler(lv_event_t *e)
478	{
479	    switch (g_tong_state) {
480	    case TONG_STATE_IDLE: {
481	        /* 开始连接 */
482	        if (!settings_wifi_is_connected()) {
483	            tong_update_ui_state(TONG_STATE_ERROR, "请先连接WiFi");
484	            return;
485	        }
486	
487	        tong_update_ui_state(TONG_STATE_CONNECTING, NULL);
488	
489	        g_cancel_requested = false;
490	        g_starting = true;
491	        g_start_ret = -1;
492	
493	        volc_voice_init();
494	
495	        pthread_attr_t attr;
496	        pthread_attr_init(&attr);
497	        pthread_attr_setstacksize(&attr, START_THREAD_STACK);
498	        int ret = pthread_create(&g_start_tid, &attr, voice_start_thread, NULL);
499	        pthread_attr_destroy(&attr);
500	
501	        if (ret != 0) {
502	            TONG_LOG("[TONG] start thread create failed: %d\n", ret);
503	            g_starting = false;
504	            tong_update_ui_state(TONG_STATE_ERROR, "无法启动语音服务");
505	        }
506	        break;
507	    }
508	
509	    case TONG_STATE_CONNECTING:
510	        /* 取消连接 — 设置标志，等待启动线程超时返回 */
511	        g_cancel_requested = true;
512	        if (tong_action_btn_label)
513	            lv_label_set_text(tong_action_btn_label, "取消中...");
514	        break;
515	
516	    case TONG_STATE_CONNECTED:
517	    case TONG_STATE_LISTENING:
518	    case TONG_STATE_THINKING:
519	        /* 结束对话 */
520	        volc_voice_stop();
521	        /* volc_voice_stop会发送DISCONNECTED回调，由定时器处理UI更新 */
522	        break;
523	
524	    case TONG_STATE_SPEAKING:
525	        /* 打断TTS播放 */
526	        volc_voice_interrupt();
527	        break;
528	
529	    case TONG_STATE_ERROR:
530	        /* 重试 */
531	        tong_update_ui_state(TONG_STATE_CONNECTING, NULL);
532	        g_cancel_requested = false;
533	        g_starting = true;
534	        g_start_ret = -1;
535	
536	        volc_voice_init();
537	
538	        {
539	            pthread_attr_t attr;
540	            pthread_attr_init(&attr);
541	            pthread_attr_setstacksize(&attr, START_THREAD_STACK);
542	            int ret = pthread_create(&g_start_tid, &attr, voice_start_thread, NULL);
543	            pthread_attr_destroy(&attr);
544	
545	            if (ret != 0) {
546	                TONG_LOG("[TONG] retry thread create failed: %d\n", ret);
547	                g_starting = false;
548	                tong_update_ui_state(TONG_STATE_ERROR, "无法启动语音服务");
549	            }
550	        }
551	        break;
552	    }
553	}
