555	static void back_btn_click_handler(lv_event_t *e)
556	{
557	    TONG_LOG("tong_ai: back button pressed\n");
558	
559	    /* 停止语音会话 */
560	    if (volc_voice_is_active()) {
561	        volc_voice_stop();
562	    }
563	
564	    /* 等待启动线程结束(如果还在运行) */
565	    if (g_starting) {
566	        g_cancel_requested = true;
