575	        lv_timer_del(g_volc_timer);
576	        g_volc_timer = NULL;
577	    }
578	
579	    /* 退出页面 */
580	    if (tong_main_base) {
581	        vw_watch_pop_page(tong_main_base);
582	        lv_obj_del(tong_main_base);
583	        tong_main_base = NULL;
