592	/* ========== 手势处理 ========== */
593	
594	static void slide_gesture_handler(lv_event_t *e)
595	{
596	    lv_event_code_t code = lv_event_get_code(e);
597	    static lv_point_t start_point = {0};
598	
599	    switch (code) {
600	    case LV_EVENT_PRESSED:
601	        lv_indev_get_point(lv_indev_active(), &start_point);
602	        break;
603	
604	    case LV_EVENT_RELEASED: {
605	        lv_point_t end_point;
606	        lv_indev_get_point(lv_indev_active(), &end_point);
607	
608	        int32_t delta_x = end_point.x - start_point.x;
609	        int32_t delta_y = end_point.y - start_point.y;
610	
611	        /* 右滑退出 */
612	        if (delta_x > 50 && abs(delta_x) > abs(delta_y)) {
613	            TONG_LOG("tong_ai: right swipe, exit\n");
614	            back_btn_click_handler(NULL);
615	        }
616	        break;
617	    }
618	
619	    default:
620	        break;
621	    }
622	}
