193	/* ========== TLS连接 ========== */
194	
195	static int tls_connect(tls_ctx_t *ctx, const char *host, const char *port)
196	{
197	    int ret;
198	    printf("[volc_e2e] tls_connect: init mbedtls contexts\n");
199	    mbedtls_ssl_init(&ctx->ssl);
200	    mbedtls_ssl_config_init(&ctx->cfg);
201	    mbedtls_net_init(&ctx->net);
202	    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
203	
204	    printf("[volc_e2e] tls_connect: seeding DRBG\n");
205	    const char *pers = "volc_e2e";
206	    ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, entropy_func,
207	        NULL, (const unsigned char *)pers, strlen(pers));
208	    if (ret != 0) {
209	        printf("[volc_e2e] ctr_drbg_seed FAILED: -0x%04x (entropy source unavailable?)\n", -ret);
210	        syslog(LOG_ERR, "[%s] ctr_drbg_seed: -0x%04x\n", TAG, -ret);
211	        return -EIO;
212	    }
213	
214	    printf("[volc_e2e] tls_connect: connecting TCP %s:%s\n", host, port);
215	    ret = mbedtls_net_connect(&ctx->net, host, port, MBEDTLS_NET_PROTO_TCP);
216	    if (ret != 0) {
217	        printf("[volc_e2e] net_connect %s:%s FAILED: -0x%04x (DNS or TCP connect failed)\n", host, port, -ret);
218	        syslog(LOG_ERR, "[%s] net_connect %s:%s: -0x%04x\n", TAG, host, port, -ret);
219	        return -ECONNREFUSED;
220	    }
221	    printf("[volc_e2e] tls_connect: TCP connected, fd=%d\n", ctx->net.fd);
222	
223	    mbedtls_net_set_block(&ctx->net);
224	
225	    struct timeval tv = { .tv_sec = 10, .tv_usec = 0 };
226	    setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
227	
228	    printf("[volc_e2e] tls_connect: configuring SSL defaults\n");
229	    ret = mbedtls_ssl_config_defaults(&ctx->cfg,
230	        MBEDTLS_SSL_IS_CLIENT, MBEDTLS_SSL_TRANSPORT_STREAM,
231	        MBEDTLS_SSL_PRESET_DEFAULT);
232	    if (ret != 0) {
233	        printf("[volc_e2e] ssl_config_defaults FAILED: -0x%04x\n", -ret);
234	        return -EIO;
235	    }
236	
237	    /* TLS 1.2 only.  Do NOT reference MBEDTLS_SSL_PROTO_TLS1_3 here:
238	     * the ESP32-S3 mbedTLS headers (esp_mbedtls.h) may define it while
239	     * the actual mbedTLS library is compiled without TLS 1.3 support.
240	     * If max_version is set to TLS 1.3 against a TLS-1.2-only library
241	     * build, mbedtls_ssl_setup() hits MBEDTLS_ERR_SSL_BAD_CONFIG
242	     * because the hybrid-TLS12-TLS13 version check is compiled out. */
243	    mbedtls_ssl_conf_min_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
244	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
245	
246	#if defined(MBEDTLS_SSL_ALPN)
247	    static const char *alpn[] = { "http/1.1", NULL };
248	    mbedtls_ssl_conf_alpn_protocols(&ctx->cfg, alpn);
249	#endif
250	
251	    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
252	    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random, &ctx->ctr_drbg);
253	
254	    printf("[volc_e2e] tls_connect: setting up SSL\n");
255	    ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg);
256	    if (ret != 0) {
257	        printf("[volc_e2e] ssl_setup FAILED: -0x%04x\n", -ret);
258	        return -EIO;
259	    }
260	
261	    mbedtls_ssl_set_hostname(&ctx->ssl, host);
262	    mbedtls_ssl_set_bio(&ctx->ssl, &ctx->net,
263	        mbedtls_net_send, mbedtls_net_recv, NULL);
264	
265	    printf("[volc_e2e] tls_connect: starting TLS handshake\n");
266	    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
267	        if (ret == MBEDTLS_ERR_SSL_WANT_READ || ret == MBEDTLS_ERR_SSL_WANT_WRITE) {
268	            printf("[volc_e2e] handshake stalled (WANT_READ/WANT_WRITE)\n");
269	            syslog(LOG_ERR, "[%s] handshake stalled\n", TAG);
270	            return -ETIMEDOUT;
271	        }
272	        printf("[volc_e2e] handshake FAILED: -0x%04x\n", -ret);
273	        syslog(LOG_ERR, "[%s] handshake: -0x%04x\n", TAG, -ret);
274	        return -EIO;
275	    }
276	
277	    /* 切换非阻塞: 防止recv线程持有互斥锁时阻塞send线程 */
278	    mbedtls_net_set_nonblock(&ctx->net);
279	
280	    printf("[volc_e2e] TLS connected to %s:%s\n", host, port);
281	    syslog(LOG_INFO, "[%s] TLS connected to %s:%s\n", TAG, host, port);
282	    return 0;
283	}
