294	/* ========== TLS I/O (互斥锁保护) ========== */
295	
296	static int tls_write_all(tls_ctx_t *ctx, const unsigned char *buf, size_t len)
297	{
298	    if (ctx == NULL || ctx->net.fd < 0) return -EINVAL;
299	
300	    pthread_mutex_lock(&s_tls_mutex);
301	    size_t written = 0;
302	    while (written < len) {
303	        int ret = mbedtls_ssl_write(&ctx->ssl, buf + written, len - written);
304	        if (ret > 0) {
305	            written += (size_t)ret;
306	        } else if (ret == MBEDTLS_ERR_SSL_WANT_WRITE || ret == MBEDTLS_ERR_SSL_WANT_READ) {
307	            pthread_mutex_unlock(&s_tls_mutex);
308	            usleep(1000);
309	            pthread_mutex_lock(&s_tls_mutex);
310	        } else if (ret == MBEDTLS_ERR_NET_CONN_RESET) {
311	            syslog(LOG_ERR, "[%s] connection reset\n", TAG);
312	            pthread_mutex_unlock(&s_tls_mutex);
313	            return -ECONNRESET;
314	        } else {
315	            syslog(LOG_ERR, "[%s] ssl_write: -0x%04x\n", TAG, -ret);
316	            pthread_mutex_unlock(&s_tls_mutex);
317	            return -EIO;
318	        }
319	    }
320	    pthread_mutex_unlock(&s_tls_mutex);
321	    return 0;
322	}
323	
324	static int tls_read_all(tls_ctx_t *ctx, unsigned char *buf, size_t len)
325	{
326	    if (ctx == NULL || ctx->net.fd < 0) return -EINVAL;
327	
328	    pthread_mutex_lock(&s_tls_mutex);
329	    size_t got = 0;
330	    while (got < len) {
331	        int ret = mbedtls_ssl_read(&ctx->ssl, buf + got, len - got);
332	        if (ret > 0) {
333	            got += (size_t)ret;
334	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
335	            syslog(LOG_INFO, "[%s] connection closed by peer\n", TAG);
336	            pthread_mutex_unlock(&s_tls_mutex);
337	            return -ECONNRESET;
338	        } else if (ret == MBEDTLS_ERR_SSL_WANT_READ || ret == MBEDTLS_ERR_SSL_WANT_WRITE) {
339	            pthread_mutex_unlock(&s_tls_mutex);
340	            usleep(10000);
341	            pthread_mutex_lock(&s_tls_mutex);
342	        } else if (ret == MBEDTLS_ERR_NET_CONN_RESET) {
343	            syslog(LOG_ERR, "[%s] connection reset\n", TAG);
344	            pthread_mutex_unlock(&s_tls_mutex);
345	            return -ECONNRESET;
346	        } else {
347	            syslog(LOG_ERR, "[%s] ssl_read: -0x%04x\n", TAG, -ret);
348	            pthread_mutex_unlock(&s_tls_mutex);
349	            return -EIO;
350	        }
351	    }
352	    pthread_mutex_unlock(&s_tls_mutex);
353	    return 0;
354	}
