356	/* ========== WebSocket握手 ========== */
357	
358	static int ws_handshake(tls_ctx_t *ctx, const char *host, const char *path)
359	{
360	    unsigned char key_raw[16];
361	    unsigned char key_b64[32];
362	    size_t key_b64_len;
363	    entropy_func(NULL, key_raw, sizeof(key_raw));
364	    mbedtls_base64_encode(key_b64, sizeof(key_b64), &key_b64_len,
365	        key_raw, sizeof(key_raw));
366	
367	    char req[1024];
368	    int n = snprintf(req, sizeof(req),
369	        "GET %s HTTP/1.1\r\n"
370	        "Host: %s\r\n"
371	        "Upgrade: websocket\r\n"
372	        "Connection: Upgrade\r\n"
373	        "Sec-WebSocket-Key: %.*s\r\n"
374	        "Sec-WebSocket-Version: 13\r\n"
375	        "X-Api-App-ID: %s\r\n"
376	        "X-Api-Access-Key: %s\r\n"
377	        "X-Api-Resource-Id: %s\r\n"
378	        "X-Api-App-Key: %s\r\n"
379	        "\r\n",
380	        path, host, (int)key_b64_len, key_b64,
381	        VOLC_APP_ID, VOLC_TOKEN, VOLC_RESOURCE, VOLC_APP_KEY);
382	
383	    if (n <= 0 || n >= (int)sizeof(req)) return -EOVERFLOW;
384	
385	    syslog(LOG_INFO, "[%s] WS handshake: %s\n", TAG, path);
386	
387	    int ret = tls_write_all(ctx, (const unsigned char *)req, (size_t)n);
388	    if (ret != 0) return ret;
389	
390	    char resp[2048];
391	    size_t rlen = 0;
392	    while (rlen < sizeof(resp) - 1) {
393	        int r = mbedtls_ssl_read(&ctx->ssl,
394	            (unsigned char *)resp + rlen, sizeof(resp) - 1 - rlen);
395	        if (r > 0) {
396	            rlen += (size_t)r;
397	            resp[rlen] = '\0';
398	            if (strstr(resp, "\r\n\r\n")) break;
399	        } else if (r == 0 || r == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
400	            return -ECONNRESET;
401	        } else if (r != MBEDTLS_ERR_SSL_WANT_READ) {
402	            return -EIO;
403	        }
404	    }
405	
406	    int status = 0;
407	    if (sscanf(resp, "HTTP/1.1 %d", &status) != 1 || status != 101) {
408	        syslog(LOG_ERR, "[%s] WS upgrade failed: HTTP %d\n", TAG, status);
409	        return -EPROTO;
410	    }
411	
412	    syslog(LOG_INFO, "[%s] WS upgrade OK\n", TAG);
413	    return 0;
414	}
