416	/* ========== WebSocket帧收发 ========== */
417	
418	static int ws_send_binary(tls_ctx_t *ctx,
419	    const unsigned char *payload, size_t plen)
420	{
421	    if (ctx == NULL || ctx->net.fd < 0) return -EINVAL;
422	
423	    unsigned char hdr[14];
424	    size_t hdr_len = 0;
425	    hdr[0] = WS_FIN_BIT | WS_OPCODE_BINARY;
426	
427	    if (plen < 126) {
428	        hdr[1] = WS_MASK_BIT | (unsigned char)plen;
429	        hdr_len = 2;
430	    } else if (plen <= 0xFFFF) {
431	        hdr[1] = WS_MASK_BIT | 126;
432	        hdr[2] = (unsigned char)(plen >> 8);
433	        hdr[3] = (unsigned char)(plen & 0xFF);
434	        hdr_len = 4;
435	    } else {
436	        hdr[1] = WS_MASK_BIT | 127;
437	        memset(hdr + 2, 0, 4);
438	        hdr[6] = (unsigned char)((plen >> 24) & 0xFF);
439	        hdr[7] = (unsigned char)((plen >> 16) & 0xFF);
440	        hdr[8] = (unsigned char)((plen >> 8) & 0xFF);
441	        hdr[9] = (unsigned char)(plen & 0xFF);
442	        hdr_len = 10;
443	    }
444	
445	    unsigned char mask[WS_MASK_KEY_LEN];
446	    entropy_func(NULL, mask, WS_MASK_KEY_LEN);
447	    memcpy(hdr + hdr_len, mask, WS_MASK_KEY_LEN);
448	    hdr_len += WS_MASK_KEY_LEN;
449	
450	    int ret = tls_write_all(ctx, hdr, hdr_len);
451	    if (ret != 0) return ret;
452	
453	    unsigned char chunk[1024];
454	    size_t sent = 0;
455	    while (sent < plen) {
456	        size_t clen = plen - sent;
457	        if (clen > sizeof(chunk)) clen = sizeof(chunk);
458	        for (size_t i = 0; i < clen; i++)
459	            chunk[i] = payload[sent + i] ^ mask[(sent + i) % 4];
460	        ret = tls_write_all(ctx, chunk, clen);
461	        if (ret != 0) return ret;
462	        sent += clen;
463	    }
464	    return 0;
465	}
466	
467	static int ws_send_pong(tls_ctx_t *ctx,
468	    const unsigned char *payload, size_t plen)
469	{
470	    unsigned char hdr[14];
471	    size_t hdr_len = 0;
472	    hdr[0] = WS_FIN_BIT | WS_OPCODE_PONG;
473	    if (plen < 126) {
474	        hdr[1] = WS_MASK_BIT | (unsigned char)plen;
475	        hdr_len = 2;
476	    } else {
477	        hdr[1] = WS_MASK_BIT | 126;
478	        hdr[2] = (unsigned char)(plen >> 8);
479	        hdr[3] = (unsigned char)(plen & 0xFF);
480	        hdr_len = 4;
481	    }
482	    unsigned char mask[WS_MASK_KEY_LEN];
483	    entropy_func(NULL, mask, WS_MASK_KEY_LEN);
484	    memcpy(hdr + hdr_len, mask, WS_MASK_KEY_LEN);
485	    hdr_len += WS_MASK_KEY_LEN;
486	    int ret = tls_write_all(ctx, hdr, hdr_len);
487	    if (ret != 0) return ret;
488	    for (size_t i = 0; i < plen; i++) {
489	        unsigned char c = payload[i] ^ mask[i % 4];
490	        ret = tls_write_all(ctx, &c, 1);
491	        if (ret != 0) return ret;
492	    }
493	    return 0;
494	}
495	
496	static int ws_recv_frame(tls_ctx_t *ctx,
497	    unsigned char *buf, size_t cap,
498	    size_t *out_len, int *out_opcode)
499	{
500	    unsigned char hdr[2];
501	    int ret = tls_read_all(ctx, hdr, 2);
502	    if (ret != 0) return ret;
503	
504	    *out_opcode = hdr[0] & 0x0F;
505	    int masked = (hdr[1] & WS_MASK_BIT) != 0;
506	    size_t plen = hdr[1] & 0x7F;
507	
508	    if (plen == 126) {
509	        unsigned char ext[2];
510	        ret = tls_read_all(ctx, ext, 2);
511	        if (ret != 0) return ret;
512	        plen = ((size_t)ext[0] << 8) | ext[1];
513	    } else if (plen == 127) {
514	        unsigned char ext[8];
515	        ret = tls_read_all(ctx, ext, 8);
516	        if (ret != 0) return ret;
517	        plen = ((size_t)ext[4] << 24) | ((size_t)ext[5] << 16)
518	            | ((size_t)ext[6] << 8) | ext[7];
519	    }
520	
521	    unsigned char mask[WS_MASK_KEY_LEN];
522	    if (masked) {
523	        ret = tls_read_all(ctx, mask, WS_MASK_KEY_LEN);
524	        if (ret != 0) return ret;
525	    }
526	
527	    if (plen > cap) {
528	        syslog(LOG_ERR, "[%s] WS frame too large: %zu > %zu\n", TAG, plen, cap);
529	        return -EOVERFLOW;
530	    }
531	
532	    if (plen > 0) {
533	        ret = tls_read_all(ctx, buf, plen);
534	        if (ret != 0) return ret;
535	        if (masked) {
536	            for (size_t i = 0; i < plen; i++) buf[i] ^= mask[i % 4];
537	        }
538	    }
539	
540	    *out_len = plen;
541	    return 0;
542	}
