544	/* ========== 火山二进制协议 ========== */
545	
546	static uint32_t read_be32(const unsigned char *buf, size_t off)
547	{
548	    return ((uint32_t)buf[off] << 24) | ((uint32_t)buf[off + 1] << 16)
549	        | ((uint32_t)buf[off + 2] << 8) | (uint32_t)buf[off + 3];
550	}
551	
552	static void write_be32(unsigned char *buf, size_t off, uint32_t val)
553	{
554	    buf[off] = (unsigned char)((val >> 24) & 0xFF);
555	    buf[off + 1] = (unsigned char)((val >> 16) & 0xFF);
556	    buf[off + 2] = (unsigned char)((val >> 8) & 0xFF);
557	    buf[off + 3] = (unsigned char)(val & 0xFF);
558	}
559	
560	static int send_client_frame(tls_ctx_t *ctx, uint32_t event_id,
561	    const char *session_id, const unsigned char *payload, size_t plen)
562	{
563	    if (ctx == NULL || ctx->net.fd < 0) return -EINVAL;
564	
565	    size_t sid_len = session_id ? strlen(session_id) : 0;
566	    bool is_connect_event = (event_id == EVENT_START_CONNECTION
567	                             || event_id == EVENT_FINISH_CONNECTION);
568	
569	    size_t frame_len;
570	    if (is_connect_event)
571	        frame_len = VOLC_HDR_SIZE + 4 + 4 + plen;
572	    else
573	        frame_len = VOLC_HDR_SIZE + 4 + 4 + sid_len + 4 + plen;
574	
575	    unsigned char *frame = malloc(frame_len);
576	    if (!frame) return -ENOMEM;
577	
578	    size_t off = 0;
579	    frame[off++] = VOLC_PROTO_VER;
580	    frame[off++] = VOLC_MSG_FULL_REQ | VOLC_FLAG_EVENT;
581	    frame[off++] = VOLC_SER_JSON;
582	    frame[off++] = 0x00;
583	
584	    write_be32(frame, off, event_id);
585	    off += 4;
586	
587	    if (!is_connect_event) {
588	        write_be32(frame, off, (uint32_t)sid_len);
589	        off += 4;
590	        if (sid_len > 0) {
591	            memcpy(frame + off, session_id, sid_len);
592	            off += sid_len;
593	        }
594	    }
595	
596	    write_be32(frame, off, (uint32_t)plen);
597	    off += 4;
598	    if (plen > 0) memcpy(frame + off, payload, plen);
599	
600	    int ret = ws_send_binary(ctx, frame, frame_len);
601	    free(frame);
602	    return ret;
603	}
604	
605	static int send_audio_frame(tls_ctx_t *ctx, const char *session_id,
606	    const unsigned char *audio, size_t alen)
607	{
608	    if (ctx == NULL || ctx->net.fd < 0 || session_id == NULL) return -EINVAL;
609	
610	    size_t sid_len = strlen(session_id);
611	    if (sid_len == 0) return -EINVAL;
612	
613	    size_t frame_len = VOLC_HDR_SIZE + 4 + 4 + sid_len + 4 + alen;
614	    unsigned char *frame = malloc(frame_len);
615	    if (!frame) return -ENOMEM;
616	
617	    size_t off = 0;
618	    frame[off++] = VOLC_PROTO_VER;
619	    frame[off++] = VOLC_MSG_AUDIO_REQ | VOLC_FLAG_EVENT;
620	    frame[off++] = VOLC_SER_RAW;
621	    frame[off++] = 0x00;
622	
623	    write_be32(frame, off, EVENT_TASK_REQUEST);
624	    off += 4;
625	
626	    write_be32(frame, off, (uint32_t)sid_len);
627	    off += 4;
628	    memcpy(frame + off, session_id, sid_len);
629	    off += sid_len;
630	
631	    write_be32(frame, off, (uint32_t)alen);
632	    off += 4;
633	    memcpy(frame + off, audio, alen);
634	
635	    int ret = ws_send_binary(ctx, frame, frame_len);
636	    free(frame);
637	    return ret;
638	}
