751	/* ========== 服务器帧解析 ========== */
752	
753	static int parse_server_frame(const unsigned char *frame, size_t frame_len,
754	    uint32_t *out_event, char *session_id, size_t sid_cap,
755	    unsigned char **out_payload, size_t *out_plen)
756	{
757	    if (frame_len < VOLC_HDR_SIZE) return -EINVAL;
758	
759	    uint8_t msg_type = frame[1] & 0xF0;
760	
761	    if (msg_type == VOLC_MSG_ERROR) {
762	        if (frame_len >= VOLC_HDR_SIZE + 8) {
763	            *out_event = EVENT_DIALOG_ERROR;
764	            uint32_t err_code = read_be32(frame, 4);
765	            uint32_t err_len = read_be32(frame, 8);
766	            syslog(LOG_ERR, "[%s] server error: code=%u\n", TAG, err_code);
767	            if (err_len > 0 && VOLC_HDR_SIZE + 8 + err_len <= frame_len) {
768	                *out_payload = (unsigned char *)(frame + VOLC_HDR_SIZE + 8);
769	                *out_plen = err_len;
770	            }
771	            session_id[0] = '\0';
772	            return 0;
773	        }
774	        return -EINVAL;
775	    }
776	
777	    if (msg_type != VOLC_MSG_FULL_RESP && msg_type != VOLC_MSG_AUDIO_RESP)
778	        return -EINVAL;
779	
780	    *out_event = read_be32(frame, 4);
781	
782	    if (msg_type == VOLC_MSG_AUDIO_RESP)
783	        *out_event = EVENT_TTS_RESPONSE;
784	
785	    size_t off = 8;
786	    if (off + 4 > frame_len) return -EINVAL;
787	    uint32_t sid_len = read_be32(frame, off);
788	    off += 4;
789	
790	    if (sid_len > 0) {
791	        if (off + sid_len > frame_len) return -EINVAL;
792	        if (sid_len >= sid_cap) sid_len = sid_cap - 1;
793	        memcpy(session_id, frame + off, sid_len);
794	        session_id[sid_len] = '\0';
795	        off += sid_len;
796	    } else {
797	        session_id[0] = '\0';
798	    }
799	
800	    if (off + 4 > frame_len) {
801	        *out_payload = NULL;
802	        *out_plen = 0;
803	        return 0;
804	    }
805	    uint32_t plen = read_be32(frame, off);
806	    off += 4;
807	
808	    if (off + plen > frame_len) return -EINVAL;
809	    *out_payload = (unsigned char *)(frame + off);
810	    *out_plen = plen;
811	    return 0;
812	}
