814	/* ========== 音频采集 ========== */
815	
816	static void capture_release_frame(struct ap_buffer_s *apb);
817	
818	static int capture_init(void)
819	{
820	    int fd = open(CAPTURE_DEVICE, O_RDWR | O_CLOEXEC);
821	    if (fd < 0) {
822	        syslog(LOG_ERR, "[%s] open(%s): %d\n", TAG, CAPTURE_DEVICE, errno);
823	        return -errno;
824	    }
825	
826	    if (ioctl(fd, AUDIOIOC_RESERVE, 0) < 0) {
827	        syslog(LOG_ERR, "[%s] RESERVE: %d\n", TAG, errno);
828	        close(fd); return -errno;
829	    }
830	
831	    struct audio_caps_desc_s cap_desc;
832	    memset(&cap_desc, 0, sizeof(cap_desc));
833	    cap_desc.caps.ac_len = sizeof(cap_desc.caps);
834	    cap_desc.caps.ac_type = AUDIO_TYPE_INPUT;
835	    cap_desc.caps.ac_channels = VOLC_CAPTURE_CHANNELS;
836	    cap_desc.caps.ac_chmap = 0;
837	    cap_desc.caps.ac_controls.hw[0] = VOLC_CAPTURE_RATE;
838	    cap_desc.caps.ac_controls.b[3] = (uint8_t)(VOLC_CAPTURE_RATE >> 16);
839	    cap_desc.caps.ac_controls.b[2] = VOLC_CAPTURE_BITS;
840	    cap_desc.caps.ac_subtype = AUDIO_FMT_PCM;
841	
842	    if (ioctl(fd, AUDIOIOC_CONFIGURE, (uintptr_t)&cap_desc) < 0) {
843	        syslog(LOG_ERR, "[%s] CONFIGURE: %d\n", TAG, errno);
844	        ioctl(fd, AUDIOIOC_RELEASE, 0); close(fd); return -errno;
845	    }
846	
847	    struct ap_buffer_info_s buf_info;
848	    memset(&buf_info, 0, sizeof(buf_info));
849	    if (ioctl(fd, AUDIOIOC_GETBUFFERINFO, (uintptr_t)&buf_info) != OK) {
850	        buf_info.nbuffers = 4; buf_info.buffer_size = 4096;
851	    }
852	    int nbufs = buf_info.nbuffers;
853	    if (nbufs < 1) nbufs = 4;
854	
855	    struct ap_buffer_s **buffers = calloc((size_t)nbufs, sizeof(void *));
856	    if (!buffers) { ioctl(fd, AUDIOIOC_RELEASE, 0); close(fd); return -ENOMEM; }
857	
858	    struct audio_buf_desc_s buf_desc;
859	    for (int i = 0; i < nbufs; i++) {
860	        memset(&buf_desc, 0, sizeof(buf_desc));
861	        buf_desc.numbytes = buf_info.buffer_size;
862	        buf_desc.u.pbuffer = &buffers[i];
863	        if (ioctl(fd, AUDIOIOC_ALLOCBUFFER, (uintptr_t)&buf_desc) < 0) {
864	            while (--i >= 0) ioctl(fd, AUDIOIOC_FREEBUFFER, (uintptr_t)&buffers[i]);
865	            free(buffers); ioctl(fd, AUDIOIOC_RELEASE, 0); close(fd);
866	            return -ENOMEM;
867	        }
868	    }
869	
870	    struct mq_attr attr;
871	    attr.mq_maxmsg = nbufs + 8;
872	    attr.mq_msgsize = sizeof(struct audio_msg_s);
873	    attr.mq_curmsgs = 0;
874	    attr.mq_flags = 0;
875	
876	    snprintf(s_mq_name, sizeof(s_mq_name), "/tmp/e2e_cap%p", (void *)&s_cap_fd);
877	    mq_unlink(s_mq_name);
878	    s_cap_mq = mq_open(s_mq_name, O_RDWR | O_CREAT, 0644, &attr);
879	    if (s_cap_mq == (mqd_t)-1) {
880	        for (int i = 0; i < nbufs; i++) ioctl(fd, AUDIOIOC_FREEBUFFER, (uintptr_t)&buffers[i]);
881	        free(buffers); ioctl(fd, AUDIOIOC_RELEASE, 0); close(fd);
882	        return -errno;
883	    }
884	    ioctl(fd, AUDIOIOC_REGISTERMQ, (uintptr_t)s_cap_mq);
885	
886	    for (int i = 0; i < nbufs; i++) {
887	        memset(&buf_desc, 0, sizeof(buf_desc));
888	        buf_desc.u.buffer = buffers[i];
889	        ioctl(fd, AUDIOIOC_ENQUEUEBUFFER, (uintptr_t)&buf_desc);
890	    }
891	
892	    free(buffers);
893	    s_cap_fd = fd;
894	    syslog(LOG_INFO, "[%s] capture ready\n", TAG);
895	    return 0;
896	}
897	
898	static int capture_start(void) { return ioctl(s_cap_fd, AUDIOIOC_START, 0); }
899	static int capture_stop(void) { return ioctl(s_cap_fd, AUDIOIOC_STOP, 0); }
900	
901	static int capture_read_frame(struct ap_buffer_s **out_apb,
902	    const uint8_t **out_pcm, size_t *out_len)
903	{
904	    struct audio_msg_s msg;
905	    struct timespec ts;
906	    clock_gettime(CLOCK_REALTIME, &ts);
907	    ts.tv_nsec += 100000000;
908	    if (ts.tv_nsec >= 1000000000) { ts.tv_sec++; ts.tv_nsec -= 1000000000; }
909	
910	    ssize_t size = mq_timedreceive(s_cap_mq, (char *)&msg, sizeof(msg), NULL, &ts);
911	    if (size != sizeof(msg)) {
912	        if (errno == ETIMEDOUT) return -ETIMEDOUT;
913	        return -EIO;
914	    }
915	
916	    if (msg.msg_id == AUDIO_MSG_DEQUEUE && msg.u.ptr) {
917	        struct ap_buffer_s *apb = (struct ap_buffer_s *)msg.u.ptr;
918	        if (apb->samp == NULL || apb->nbytes == 0) {
919	            capture_release_frame(apb);
920	            return -EAGAIN;
921	        }
922	        *out_apb = apb;
923	        *out_pcm = apb->samp;
924	        *out_len = apb->nbytes;
925	        return 0;
926	    }
927	    return -EIO;
928	}
929	
930	static void capture_release_frame(struct ap_buffer_s *apb)
931	{
932	    if (apb == NULL || s_cap_fd < 0) return;
933	    struct audio_buf_desc_s buf_desc;
934	    memset(&buf_desc, 0, sizeof(buf_desc));
935	    buf_desc.u.buffer = apb;
936	    ioctl(s_cap_fd, AUDIOIOC_ENQUEUEBUFFER, (uintptr_t)&buf_desc);
937	}
938	
939	static void capture_deinit(void)
940	{
941	    if (s_cap_fd >= 0) {
942	        ioctl(s_cap_fd, AUDIOIOC_STOP, 0);
943	        usleep(50000);
944	        ioctl(s_cap_fd, AUDIOIOC_RELEASE, 0);
945	        close(s_cap_fd);
946	        s_cap_fd = -1;
947	    }
948	    if (s_cap_mq != (mqd_t)-1) {
949	        mq_close(s_cap_mq);
950	        mq_unlink(s_mq_name);
951	        s_cap_mq = (mqd_t)-1;
952	    }
953	}
