955	/* ========== 音频播放 (nxplayer + WAV) ========== */
956	
957	typedef struct {
958	    char riff_id[4]; uint32_t riff_size; char wave_id[4];
959	    char fmt_id[4]; uint32_t fmt_size; uint16_t audio_format;
960	    uint16_t num_channels; uint32_t sample_rate; uint32_t byte_rate;
961	    uint16_t block_align; uint16_t bits_per_sample;
962	    char data_id[4]; uint32_t data_size;
963	} wav_header_t;
964	
965	static void write_wav_header(wav_header_t *hdr, uint32_t pcm_size)
966	{
967	    memcpy(hdr->riff_id, "RIFF", 4);
968	    hdr->riff_size = 36 + pcm_size;
969	    memcpy(hdr->wave_id, "WAVE", 4);
970	    memcpy(hdr->fmt_id, "fmt ", 4);
971	    hdr->fmt_size = 16;
972	    hdr->audio_format = 1;
973	    hdr->num_channels = VOLC_I2S_CHANNELS;
974	    hdr->sample_rate = VOLC_PLAYBACK_RATE;
975	    hdr->byte_rate = VOLC_PLAYBACK_RATE * VOLC_I2S_CHANNELS * (VOLC_PLAYBACK_BITS / 8);
976	    hdr->block_align = VOLC_I2S_CHANNELS * (VOLC_PLAYBACK_BITS / 8);
977	    hdr->bits_per_sample = VOLC_PLAYBACK_BITS;
978	    memcpy(hdr->data_id, "data", 4);
979	    hdr->data_size = pcm_size;
980	}
981	
982	static int playback_init(void)
983	{
984	    if (!s_pcm_buf) {
985	        s_pcm_buf = malloc(TTS_BUF_CAP);
986	        if (!s_pcm_buf) {
987	            syslog(LOG_ERR, "[%s] PCM buffer alloc failed\n", TAG);
988	            return -ENOMEM;
989	        }
990	    }
991	    s_pcm_len = 0;
992	    syslog(LOG_INFO, "[%s] playback initialized\n", TAG);
993	    return 0;
994	}
995	
996	static void playback_write(const unsigned char *data, size_t len)
997	{
998	    if (s_pcm_buf && s_playing) {
999	        size_t num_samples = len / 2;
1000	        size_t out_len = num_samples * 4;
1001	        if (s_pcm_len + out_len <= TTS_BUF_CAP) {
1002	            const int16_t *mono = (const int16_t *)data;
1003	            int16_t *stereo = (int16_t *)(s_pcm_buf + s_pcm_len);
1004	            for (size_t i = 0; i < num_samples; i++) {
1005	                stereo[i * VOLC_I2S_CHANNELS] = mono[i];
1006	                stereo[i * VOLC_I2S_CHANNELS + 1] = mono[i];
1007	            }
1008	            s_pcm_len += out_len;
1009	        }
1010	    }
1011	}
1012	
1013	static void playback_stop(void)
1014	{
1015	    if (s_pcm_buf && s_pcm_len > 0) {
1016	        uint32_t byte_rate = VOLC_PLAYBACK_RATE * VOLC_I2S_CHANNELS * (VOLC_PLAYBACK_BITS / 8);
1017	        long duration_ms = (long)(s_pcm_len * 1000 / byte_rate) + 500;
1018	
1019	        const char *wav_path = "/tmp/e2e_tts.wav";
1020	        int fd = open(wav_path, O_WRONLY | O_CREAT | O_TRUNC, 0666);
1021	        if (fd >= 0) {
1022	            wav_header_t hdr;
1023	            write_wav_header(&hdr, (uint32_t)s_pcm_len);
1024	            write(fd, &hdr, sizeof(hdr));
1025	            write(fd, s_pcm_buf, s_pcm_len);
1026	            close(fd);
1027	            sync();
1028	            syslog(LOG_INFO, "[%s] WAV: %zu bytes (~%ldms)\n", TAG, s_pcm_len, duration_ms);
1029	
1030	            capture_stop();
1031	            usleep(50000);
1032	
1033	            if (s_nxplayer) {
1034	                nxplayer_stop(s_nxplayer);
1035	                nxplayer_release(s_nxplayer);
1036	                s_nxplayer = NULL;
1037	            }
1038	            s_nxplayer = nxplayer_create();
1039	            if (s_nxplayer) {
1040	                nxplayer_setdevice(s_nxplayer, "/dev/audio/pcm0");
1041	                int play_ret = nxplayer_playraw(s_nxplayer, wav_path,
1042	                    AUDIO_FMT_PCM, 0, VOLC_I2S_CHANNELS, VOLC_PLAYBACK_BITS,
1043	                    VOLC_PLAYBACK_RATE, 0);
1044	                if (play_ret < 0) {
1045	                    syslog(LOG_ERR, "[%s] playraw failed: %d\n", TAG, play_ret);
1046	                    nxplayer_release(s_nxplayer);
1047	                    s_nxplayer = NULL;
1048	                }
1049	            }
1050	
1051	            struct timespec now;
1052	            clock_gettime(CLOCK_MONOTONIC, &now);
1053	            long cooldown_ms = duration_ms + 1000;
1054	            s_cooldown_until.tv_sec = now.tv_sec + cooldown_ms / 1000;
1055	            s_cooldown_until.tv_nsec = now.tv_nsec + (cooldown_ms % 1000) * 1000000L;
1056	            if (s_cooldown_until.tv_nsec >= 1000000000L) {
1057	                s_cooldown_until.tv_sec++;
1058	                s_cooldown_until.tv_nsec -= 1000000000L;
1059	            }
1060	            s_cooldown_active = true;
1061	        }
1062	    }
1063	
1064	    if (s_pcm_buf) { free(s_pcm_buf); s_pcm_buf = NULL; }
1065	    s_pcm_len = 0;
1066	}
1067	
1068	/* ========== 本地音频播放（提示音） ========== */
1069	
1070	void volc_play_local_wav(const char *path)
1071	{
1072	    if (!path || !path[0]) return;
1073	
1074	    syslog(LOG_INFO, "[%s] playing local wav: %s\n", TAG, path);
1075	
1076	    /* 停止采集，避免音频冲突 */
1077	    capture_stop();
1078	    usleep(50000);
1079	
1080	    /* 释放已有播放器 */
1081	    if (s_nxplayer) {
1082	        nxplayer_stop(s_nxplayer);
1083	        nxplayer_release(s_nxplayer);
1084	        s_nxplayer = NULL;
1085	    }
1086	
1087	    /* 创建播放器播放SD卡WAV */
1088	    s_nxplayer = nxplayer_create();
1089	    if (s_nxplayer) {
1090	        nxplayer_setdevice(s_nxplayer, "/dev/audio/pcm0");
1091	        int ret = nxplayer_playraw(s_nxplayer, path,
1092	            AUDIO_FMT_PCM, 0, VOLC_I2S_CHANNELS, VOLC_PLAYBACK_BITS,
1093	            VOLC_PLAYBACK_RATE, 0);
1094	        if (ret < 0) {
1095	            syslog(LOG_ERR, "[%s] play local wav failed: %d (path=%s)\n",
1096	                TAG, ret, path);
1097	            nxplayer_release(s_nxplayer);
1098	            s_nxplayer = NULL;
1099	            /* 即使播放失败也要恢复采集 */
1100	        }
1101	    }
1102	
1103	    /* 设置冷却时间 (~4秒，足够播放提示音) */
1104	    struct timespec now;
1105	    clock_gettime(CLOCK_MONOTONIC, &now);
1106	    s_cooldown_until.tv_sec  = now.tv_sec + 4;
1107	    s_cooldown_until.tv_nsec = now.tv_nsec;
1108	    s_cooldown_active = true;
1109	    s_playing = false;
1110	}
