1112	/* ========== 接收线程 ========== */
1113	
1114	static void *recv_thread(void *arg)
1115	{
1116	    (void)arg;
1117	    unsigned char *buf = malloc(WS_BUF_SIZE);
1118	    if (!buf) {
1119	        syslog(LOG_ERR, "[%s] recv: alloc failed\n", TAG);
1120	        return NULL;
1121	    }
1122	
1123	    while (s_running) {
1124	        size_t frame_len = 0;
1125	        int opcode = 0;
1126	        int ret = ws_recv_frame(s_tls, buf, WS_BUF_SIZE, &frame_len, &opcode);
1127	
1128	        if (ret != 0) {
1129	            if (s_running) syslog(LOG_ERR, "[%s] recv error: %d\n", TAG, ret);
1130	            break;
1131	        }
1132	
1133	        if (opcode == WS_OPCODE_CLOSE) {
1134	            syslog(LOG_INFO, "[%s] server close\n", TAG);
1135	            break;
1136	        }
1137	        if (opcode == WS_OPCODE_PING) {
1138	            pthread_mutex_lock(&s_tls_mutex);
1139	            ws_send_pong(s_tls, buf, frame_len);
1140	            pthread_mutex_unlock(&s_tls_mutex);
1141	            continue;
1142	        }
1143	        if (opcode != WS_OPCODE_BINARY) continue;
1144	
1145	        uint32_t event_id = 0;
1146	        char session_id[VOLC_SESSION_ID_LEN + 1] = {0};
1147	        unsigned char *payload = NULL;
1148	        size_t plen = 0;
1149	
1150	        ret = parse_server_frame(buf, frame_len, &event_id,
1151	            session_id, sizeof(session_id), &payload, &plen);
1152	        if (ret != 0) {
1153	            syslog(LOG_ERR, "[%s] parse error: %d\n", TAG, ret);
1154	            continue;
1155	        }
1156	
1157	        switch (event_id) {
1158	        case EVENT_CONNECTION_STARTED:
1159	            syslog(LOG_INFO, "[%s] ConnectionStarted\n", TAG);
1160	            break;
1161	
1162	        case EVENT_CONNECTION_FAILED:
1163	            syslog(LOG_ERR, "[%s] ConnectionFailed\n", TAG);
1164	            s_running = false;
1165	            notify_ui(VOLC_CB_ERROR_MSG, "连接失败");
1166	            break;
1167	
1168	        case EVENT_CONNECTION_FINISHED:
1169	            syslog(LOG_INFO, "[%s] ConnectionFinished\n", TAG);
1170	            s_running = false;
1171	            break;
1172	
1173	        case EVENT_SESSION_STARTED: {
1174	            syslog(LOG_INFO, "[%s] SessionStarted\n", TAG);
1175	            s_session_active = true;
1176	            if (plen > 0) {
1177	                char *json = strndup((const char *)payload, plen);
1178	                if (json) {
1179	                    cJSON *root = cJSON_Parse(json);
1180	                    if (root) {
1181	                        cJSON *did = cJSON_GetObjectItem(root, "dialog_id");
1182	                        if (cJSON_IsString(did))
1183	                            strncpy(s_dialog_id, did->valuestring, sizeof(s_dialog_id) - 1);
1184	                        cJSON_Delete(root);
1185	                    }
1186	                    free(json);
1187	                }
1188	            }
1189	            notify_ui(VOLC_CB_CONNECTED, NULL);
1190	            notify_state(VOLC_UI_CONNECTED);
1191	            break;
1192	        }
1193	
1194	        case EVENT_SESSION_FINISHED:
1195	            syslog(LOG_INFO, "[%s] SessionFinished\n", TAG);
1196	            s_session_active = false;
1197	            break;
1198	
1199	        case EVENT_SESSION_FAILED:
1200	            syslog(LOG_ERR, "[%s] SessionFailed\n", TAG);
1201	            s_session_active = false;
1202	            notify_ui(VOLC_CB_ERROR_MSG, "会话失败");
1203	            break;
1204	
1205	        case EVENT_ASR_INFO:
1206	            syslog(LOG_INFO, "[%s] ASRInfo (user speaking)\n", TAG);
1207	            s_asr_buf[0] = '\0';  /* 新轮次，清空累积文本 */
1208	            if (s_playing && !s_cooldown_active) {
1209	                playback_stop();
1210	                playback_init();
1211	            }
1212	            notify_state(VOLC_UI_LISTENING);
1213	            break;
1214	
1215	        case EVENT_ASR_RESPONSE:
1216	            if (plen > 0) {
1217	                char *json = strndup((const char *)payload, plen);
1218	                if (json) {
1219	                    cJSON *root = cJSON_Parse(json);
1220	                    if (root) {
1221	                        cJSON *results = cJSON_GetObjectItem(root, "results");
1222	                        if (cJSON_IsArray(results) && cJSON_GetArraySize(results) > 0) {
1223	                            cJSON *first = cJSON_GetArrayItem(results, 0);
1224	                            cJSON *text = cJSON_GetObjectItem(first, "text");
1225	                            cJSON *is_interim = cJSON_GetObjectItem(first, "is_interim");
1226	                            if (cJSON_IsString(text) && text->valuestring[0]) {
1227	                                const char *t = text->valuestring;
1228	                                bool interim = cJSON_IsTrue(is_interim);
1229	
1230	                                if (!interim) {
1231	                                    bool skip_ai = false;
1232	
1233	                                    /* 仅打印最终识别结果到syslog */
1234	                                    syslog(LOG_INFO, "[%s] ASR: \"%s\"\n", TAG, t);
1235	
1236	                                    /* 智能家居指令检测（优先于UI模式切换，
1237	                                     * 避免"打开客厅灯"中的"打开"误触发策略2） */
1238	                                    int hc_ret = home_control_voice_execute(t);
1239	                                    if (hc_ret == HOME_CTRL_NET_FAIL) {
1240	                                        /* 匹配到设备但网络失败 */
1241	                                        syslog(LOG_INFO,
1242	                                            "[%s] home ctrl net fail: \"%s\"\n",
1243	                                            TAG, t);
1244	                                        volc_play_local_wav(HOME_CTRL_FAIL_WAV);
1245	                                        skip_ai = true;
1246	                                    } else if (hc_ret == HOME_CTRL_NO_MATCH) {
1247	                                        /* 有开关动作词但未匹配到设备 */
1248	                                        syslog(LOG_INFO,
1249	                                            "[%s] home ctrl no match: \"%s\"\n",
1250	                                            TAG, t);
1251	                                        volc_play_local_wav(HOME_CTRL_NOT_FOUND_WAV);
1252	                                        skip_ai = true;
1253	                                    }
1254	                                    /* HOME_CTRL_OK: 指令成功，正常AI对话
1255	                                     * HOME_CTRL_NONE: 无关指令，正常AI对话 */
1256	
1257	                                    if (!skip_ai) {
1258	                                        /* 累积最终文本到静态缓冲区 */
1259	                                        strncat(s_asr_buf, t,
1260	                                            sizeof(s_asr_buf) - strlen(s_asr_buf) - 1);
1261	
1262	                                        /* 多策略关键词检测:
1263	                                         * 策略1: 完整短语匹配(含发音变体) */
1264	                                        int matched = 0;
1265	                                        if (strstr_any(s_asr_buf, VAR_CHAOWAN) ||
1266	                                            strstr_any(s_asr_buf, VAR_BIAOQING)) {
1267	                                            matched = 1;
1268	                                        }
1269	
1270	                                        /* 策略2: 动作词 + 目标词变体 组合匹配
1271	                                         * (更鲁棒，容忍中间杂字和发音变体) */
1272	                                        if (!matched) {
1273	                                            int has_action = 0, has_target = 0;
1274	                                            if (strstr(s_asr_buf, "切换") ||
1275	                                                strstr(s_asr_buf, "打开") ||
1276	                                                strstr(s_asr_buf, "进入") ||
1277	                                                strstr(s_asr_buf, "回到") ||
1278	                                                strstr(s_asr_buf, "返回"))
1279	                                                has_action = 1;
1280	                                            if (strstr_any(s_asr_buf, VAR_CHAOWAN) ||
1281	                                                strstr_any(s_asr_buf, VAR_BIAOQING) ||
1282	                                                strstr_any(s_asr_buf, VAR_BIOPAN))
1283	                                                has_target = 1;
1284	                                            if (has_action && has_target)
1285	                                                matched = 1;
1286	                                        }
1287	
1288	                                        if (matched) {
1289	                                            syslog(LOG_INFO,
1290	                                                "[%s] UI mode switch triggered: buf=\"%s\"\n",
1291	                                                TAG, s_asr_buf);
1292	                                            FILE *fp = fopen("/mnt/spif/ui_mode.json", "w");
1293	                                            if (fp) {
1294	                                                fprintf(fp, "{\"ui_mode\":0}\n");
1295	                                                fclose(fp);
1296	                                            }
1297	                                            axp2101_power_reset();
1298	                                            /* 不会到达这里 */
1299	                                        }
1300	                                        notify_ui(VOLC_CB_USER_TEXT, t);
1301	                                    }
1302	                                }
1303	                            }
1304	                        }
1305	                        cJSON_Delete(root);
1306	                    }
1307	                    free(json);
1308	                }
1309	            }
1310	            break;
1311	
1312	        case EVENT_ASR_ENDED:
1313	            syslog(LOG_INFO, "[%s] ASREnded\n", TAG);
1314	            s_asr_buf[0] = '\0';  /* 本轮结束，清空累积文本 */
1315	            s_playing = true;
1316	            notify_state(VOLC_UI_THINKING);
1317	            break;
1318	
1319	        case EVENT_CHAT_RESPONSE:
1320	            if (plen > 0) {
1321	                char *json = strndup((const char *)payload, plen);
1322	                if (json) {
1323	                    cJSON *root = cJSON_Parse(json);
1324	                    if (root) {
1325	                        cJSON *content = cJSON_GetObjectItem(root, "content");
1326	                        if (cJSON_IsString(content))
1327	                            notify_ui(VOLC_CB_AI_TEXT, content->valuestring);
1328	                        cJSON_Delete(root);
1329	                    }
1330	                    free(json);
1331	                }
1332	            }
1333	            break;
1334	
1335	        case EVENT_CHAT_ENDED:
1336	            syslog(LOG_INFO, "[%s] ChatEnded\n", TAG);
1337	            break;
1338	
1339	        case EVENT_TTS_SENTENCE_START:
1340	            syslog(LOG_INFO, "[%s] TTSSentenceStart\n", TAG);
1341	            s_playing = true;
1342	            notify_state(VOLC_UI_SPEAKING);
1343	            break;
1344	
1345	        case EVENT_TTS_SENTENCE_END:
1346	            syslog(LOG_INFO, "[%s] TTSSentenceEnd\n", TAG);
1347	            if (s_pcm_len > 0) {
1348	                playback_stop();
1349	                playback_init();
1350	            }
1351	            break;
1352	
1353	        case EVENT_TTS_RESPONSE:
1354	            if (plen > 0 && s_playing)
1355	                playback_write(payload, plen);
1356	            break;
1357	
1358	        case EVENT_TTS_ENDED:
1359	            syslog(LOG_INFO, "[%s] TTSEnded\n", TAG);
1360	            if (s_pcm_len > 0) {
1361	                playback_stop();
1362	                playback_init();
1363	            }
1364	            if (s_cooldown_active) {
1365	                s_playing = true;
1366	            } else {
1367	                s_playing = false;
1368	                notify_state(VOLC_UI_CONNECTED);
1369	            }
1370	            break;
1371	
1372	        case EVENT_DIALOG_ERROR:
1373	            if (plen > 0) {
1374	                char *json = strndup((const char *)payload, plen);
1375	                if (json) {
1376	                    cJSON *root = cJSON_Parse(json);
1377	                    if (root) {
1378	                        cJSON *msg = cJSON_GetObjectItem(root, "message");
1379	                        if (cJSON_IsString(msg))
1380	                            notify_ui(VOLC_CB_ERROR_MSG, msg->valuestring);
1381	                        cJSON_Delete(root);
1382	                    }
1383	                    free(json);
1384	                }
1385	            }
1386	            break;
1387	
1388	        default:
1389	            syslog(LOG_DEBUG, "[%s] Unknown event: %u\n", TAG, event_id);
1390	            break;
1391	        }
1392	    }
1393	
1394	    free(buf);
1395	    syslog(LOG_INFO, "[%s] recv thread exit\n", TAG);
1396	    return NULL;
1397	}
