1399	/* ========== 发送线程 (采集+发送) ========== */
1400	
1401	static void *send_thread(void *arg)
1402	{
1403	    (void)arg;
1404	
1405	    if (capture_init() != 0) {
1406	        syslog(LOG_ERR, "[%s] capture init failed\n", TAG);
1407	        return NULL;
1408	    }
1409	    capture_start();
1410	
1411	    syslog(LOG_INFO, "[%s] send thread started\n", TAG);
1412	
1413	    int frame_count = 0;
1414	    int cap_retry = 0;
1415	
1416	    size_t silence_len = (VOLC_CAPTURE_RATE / 50) * (VOLC_CAPTURE_BITS / 8);
1417	    uint8_t *silence_buf = calloc(1, silence_len);
1418	    if (!silence_buf) return NULL;
1419	
1420	    while (s_running && s_session_active) {
1421	        if (s_playing && s_cooldown_active) {
1422	            struct timespec now;
1423	            clock_gettime(CLOCK_MONOTONIC, &now);
1424	            if (now.tv_sec > s_cooldown_until.tv_sec ||
1425	                (now.tv_sec == s_cooldown_until.tv_sec &&
1426	                 now.tv_nsec >= s_cooldown_until.tv_nsec)) {
1427	                s_playing = false;
1428	                s_cooldown_active = false;
1429	                syslog(LOG_INFO, "[%s] cooldown ended\n", TAG);
1430	                notify_state(VOLC_UI_CONNECTED);
1431	                if (s_nxplayer) {
1432	                    nxplayer_stop(s_nxplayer);
1433	                    usleep(100000);
1434	                    nxplayer_release(s_nxplayer);
1435	                    s_nxplayer = NULL;
1436	                }
1437	                capture_deinit();
1438	                usleep(200000);
1439	                if (capture_init() == 0) capture_start();
1440	            } else {
1441	                send_audio_frame(s_tls, s_session_id, silence_buf, silence_len);
1442	                usleep(100000);
1443	                continue;
1444	            }
1445	        }
1446	
1447	        if (s_playing || s_cooldown_active) {
1448	            send_audio_frame(s_tls, s_session_id, silence_buf, silence_len);
1449	            usleep(100000);
1450	            continue;
1451	        }
1452	
1453	        struct ap_buffer_s *apb = NULL;
1454	        const uint8_t *pcm = NULL;
1455	        size_t pcm_len = 0;
1456	
1457	        int ret = capture_read_frame(&apb, &pcm, &pcm_len);
1458	
1459	        if (ret == -ETIMEDOUT || ret == -EAGAIN) {
1460	            send_audio_frame(s_tls, s_session_id, silence_buf, silence_len);
1461	            continue;
1462	        }
1463	
1464	        if (ret != 0) {
1465	            if (s_playing || s_cooldown_active) {
1466	                send_audio_frame(s_tls, s_session_id, silence_buf, silence_len);
1467	                usleep(100000);
1468	                continue;
1469	            }
1470	            if (ret == -EIO && cap_retry < 2) {
1471	                cap_retry++;
1472	                if (s_nxplayer) nxplayer_stop(s_nxplayer);
1473	                capture_deinit();
1474	                usleep(300000);
1475	                if (capture_init() == 0) {
1476	                    capture_start();
1477	                    continue;
1478	                }
1479	            }
1480	            break;
1481	        }
1482	
1483	        if (pcm_len > 0) {
1484	            size_t mono_len = pcm_len / 2;
1485	            if (mono_len > silence_len) {
1486	                uint8_t *new_buf = calloc(1, mono_len);
1487	                if (!new_buf) { capture_release_frame(apb); break; }
1488	                free(silence_buf);
1489	                silence_buf = new_buf;
1490	                silence_len = mono_len;
1491	            }
1492	
1493	            if (!s_playing) {
1494	                const int16_t *stereo = (const int16_t *)pcm;
1495	                int16_t *mono16 = (int16_t *)silence_buf;
1496	                size_t samples = mono_len / 2;
1497	                for (size_t i = 0; i < samples; i++)
1498	                    mono16[i] = stereo[i * 2];
1499	
1500	                ret = send_audio_frame(s_tls, s_session_id, silence_buf, mono_len);
1501	                frame_count++;
1502	                if (frame_count % 100 == 1) {
1503	                    int16_t peak = 0;
1504	                    for (size_t i = 0; i < samples; i++) {
1505	                        int16_t s = mono16[i];
1506	                        if (s < 0) s = -s;
1507	                        if (s > peak) peak = s;
1508	                    }
1509	                    syslog(LOG_INFO, "[%s] audio: %d frames, peak=%d\n", TAG, frame_count, peak);
1510	                }
1511	                if (ret != 0) {
1512	                    syslog(LOG_ERR, "[%s] send audio error: %d\n", TAG, ret);
1513	                    capture_release_frame(apb);
1514	                    break;
1515	                }
1516	            } else {
1517	                send_audio_frame(s_tls, s_session_id, silence_buf, silence_len);
1518	            }
1519	            capture_release_frame(apb);
1520	        } else {
1521	            usleep(10000);
1522	            if (s_running && s_session_active)
1523	                send_audio_frame(s_tls, s_session_id, silence_buf, silence_len);
1524	        }
1525	    }
1526	
1527	    free(silence_buf);
1528	    capture_stop();
1529	    capture_deinit();
1530	    syslog(LOG_INFO, "[%s] send thread exit\n", TAG);
1531	    return NULL;
1532	}
