1543	int volc_voice_start(volc_event_cb_t cb)
1544	{
1545	    s_callback = cb;
1546	    s_running = true;
1547	    s_session_active = false;
1548	    s_interrupted = false;
1549	    s_playing = false;
1550	    s_cooldown_active = false;
1551	
1552	    notify_state(VOLC_UI_CONNECTING);
1553	
1554	    /* 堆分配TLS上下文(PSRAM), 节省DRAM */
1555	    s_tls = calloc(1, sizeof(tls_ctx_t));
1556	    if (!s_tls) {
1557	        syslog(LOG_ERR, "[%s] TLS ctx alloc failed\n", TAG);
1558	        notify_ui(VOLC_CB_ERROR_MSG, "内存不足");
1559	        s_running = false;
1560	        return -ENOMEM;
1561	    }
1562	
1563	    int ret = tls_connect(s_tls, WS_HOST, WS_PORT);
1564	    if (ret != 0) {
1565	        printf("[volc_e2e] TLS connect failed: %d\n", ret);
1566	        syslog(LOG_ERR, "[%s] TLS connect failed: %d\n", TAG, ret);
1567	        notify_ui(VOLC_CB_ERROR_MSG, "TLS连接失败");
1568	        tls_free(s_tls); free(s_tls); s_tls = NULL;
1569	        s_running = false;
1570	        return ret;
1571	    }
1572	
1573	    printf("[volc_e2e] TLS OK, starting WS handshake\n");
1574	    ret = ws_handshake(s_tls, WS_HOST, WS_PATH);
1575	    if (ret != 0) {
1576	        printf("[volc_e2e] WS handshake failed: %d\n", ret);
1577	        syslog(LOG_ERR, "[%s] WS handshake failed: %d\n", TAG, ret);
1578	        tls_free(s_tls); free(s_tls); s_tls = NULL;
1579	        notify_ui(VOLC_CB_ERROR_MSG, "WebSocket握手失败");
1580	        s_running = false;
1581	        return ret;
1582	    }
1583	
1584	    printf("[volc_e2e] WS OK, init playback\n");
1585	    ret = playback_init();
1586	    if (ret != 0) {
1587	        printf("[volc_e2e] playback_init failed: %d\n", ret);
1588	        tls_free(s_tls); free(s_tls); s_tls = NULL;
1589	        notify_ui(VOLC_CB_ERROR_MSG, "播放初始化失败");
1590	        s_running = false;
1591	        return ret;
1592	    }
1593	
1594	    printf("[volc_e2e] Sending StartConnection\n");
1595	    ret = send_start_connection(s_tls);
1596	    if (ret != 0) {
1597	        printf("[volc_e2e] StartConnection failed: %d\n", ret);
1598	        syslog(LOG_ERR, "[%s] StartConnection failed: %d\n", TAG, ret);
1599	        tls_free(s_tls); free(s_tls); s_tls = NULL;
1600	        notify_ui(VOLC_CB_ERROR_MSG, "StartConnection失败");
1601	        s_running = false;
1602	        return ret;
1603	    }
1604	
1605	    printf("[volc_e2e] Starting recv thread\n");
1606	    pthread_create(&s_recv_tid, NULL, recv_thread, NULL);
1607	
1608	    printf("[volc_e2e] Waiting for ConnectionStarted...\n");
1609	    for (int i = 0; i < 50 && s_running; i++) usleep(100000);
1610	    if (!s_running) {
1611	        printf("[volc_e2e] ConnectionStarted timeout\n");
1612	        syslog(LOG_ERR, "[%s] ConnectionStarted timeout\n", TAG);
1613	        goto fail;
1614	    }
1615	    printf("[volc_e2e] ConnectionStarted OK\n");
1616	
1617	    printf("[volc_e2e] Sending StartSession\n");
1618	    ret = send_start_session(s_tls, s_session_id, DEFAULT_SPEAKER);
1619	    if (ret != 0) {
1620	        printf("[volc_e2e] StartSession failed: %d\n", ret);
1621	        syslog(LOG_ERR, "[%s] StartSession failed: %d\n", TAG, ret);
1622	        goto fail;
1623	    }
1624	
1625	    printf("[volc_e2e] Waiting for SessionStarted...\n");
1626	    for (int i = 0; i < 100 && s_running && !s_session_active; i++) usleep(100000);
1627	    if (!s_running || !s_session_active) {
1628	        printf("[volc_e2e] SessionStarted timeout\n");
1629	        syslog(LOG_ERR, "[%s] SessionStarted timeout\n", TAG);
1630	        goto fail;
1631	    }
1632	
1633	    pthread_create(&s_send_tid, NULL, send_thread, NULL);
1634	
1635	    syslog(LOG_INFO, "[%s] Voice session active\n", TAG);
1636	    return 0;
1637	
1638	fail:
1639	    s_running = false;
1640	    if (s_recv_tid) { pthread_join(s_recv_tid, NULL); s_recv_tid = 0; }
1641	    playback_stop();
1642	    if (s_nxplayer) { nxplayer_release(s_nxplayer); s_nxplayer = NULL; }
1643	    capture_deinit();
1644	    if (s_tls) {
1645	        tls_free(s_tls);
1646	        free(s_tls);
1647	        s_tls = NULL;
1648	    }
1649	    notify_ui(VOLC_CB_ERROR_MSG, "会话启动失败");
1650	    return -EIO;
1651	}
1652	
1653	void volc_voice_stop(void)
1654	{
1655	    if (!s_running) return;
1656	
1657	    s_running = false;
1658	    s_session_active = false;
1659	
1660	    if (s_recv_tid) { pthread_join(s_recv_tid, NULL); s_recv_tid = 0; }
1661	    if (s_send_tid) { pthread_join(s_send_tid, NULL); s_send_tid = 0; }
1662	
1663	    if (s_tls && s_tls->net.fd >= 0) {
1664	        send_finish_session(s_tls, s_session_id);
1665	        usleep(100000);
1666	        send_finish_connection(s_tls);
1667	        usleep(100000);
1668	    }
1669	
1670	    playback_stop();
1671	    if (s_nxplayer) { nxplayer_release(s_nxplayer); s_nxplayer = NULL; }
1672	    capture_deinit();
1673	    if (s_tls) {
1674	        tls_free(s_tls);
1675	        free(s_tls);
1676	        s_tls = NULL;
1677	    }
1678	
1679	    notify_ui(VOLC_CB_DISCONNECTED, NULL);
1680	    notify_state(VOLC_UI_IDLE);
1681	
1682	    syslog(LOG_INFO, "[%s] Voice session stopped\n", TAG);
1683	}
1684	
1685	bool volc_voice_is_active(void)
1686	{
1687	    return s_running && s_session_active;
1688	}
1689	
1690	void volc_voice_interrupt(void)
1691	{
1692	    if (s_playing) {
1693	        playback_stop();
1694	        playback_init();
1695	        s_playing = false;
1696	        s_cooldown_active = false;
1697	        if (s_nxplayer) {
1698	            nxplayer_stop(s_nxplayer);
1699	            usleep(100000);
1700	            nxplayer_release(s_nxplayer);
1701	            s_nxplayer = NULL;
1702	        }
1703	        capture_deinit();
1704	        usleep(200000);
1705	        if (capture_init() == 0) capture_start();
1706	        notify_state(VOLC_UI_CONNECTED);
1707	        syslog(LOG_INFO, "[%s] playback interrupted\n", TAG);
1708	    }
1709	}
