91	#define DISCOVERY_PORT 9999
92	#define DISCOVERY_MAGIC "DISCOVER_REQ"
93	#define RESPONSE_MAGIC "DISCOVER_RESP"
94	#define DISCOVERY_TIMEOUT 5
95	
96	static void discover_server_info(void);
97	static int send_control_command(int cmd);
98	
99	static void discover_server_info(void)
100	{
101	    HC_LOG("Discovering server via UDP broadcast...");
102	    
103	    memset(g_server_ip, 0, sizeof(g_server_ip));
104	    g_server_port = 0;
105	    g_server_discovered = false;
106	    
107	    int sockfd;
108	    struct sockaddr_in broadcast_addr;
109	    struct sockaddr_in server_addr;
110	    struct sockaddr_in local_addr;
111	    socklen_t server_len;
112	    char buffer[256];
113	    fd_set readfds;
114	    struct timeval timeout;
115	    int ret;
116	    struct in_addr local_ip;
117	    
118	    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
119	    if (sockfd < 0) {
120	        HC_LOG("Failed to create socket");
121	        g_server_discovered = false;
122	        return;
123	    }
124	    
125	    if (netlib_get_ipv4addr("wlan0", &local_ip) == 0 && local_ip.s_addr != 0) {
126	        HC_LOG("Local wlan0 IP: %s", inet_ntoa(local_ip));
127	        
128	        memset(&local_addr, 0, sizeof(local_addr));
129	        local_addr.sin_family = AF_INET;
130	        local_addr.sin_addr = local_ip;
131	        local_addr.sin_port = 0;
132	        
133	        if (bind(sockfd, (struct sockaddr *)&local_addr, sizeof(local_addr)) < 0) {
134	            HC_LOG("Failed to bind to wlan0 interface");
135	        }
136	    } else {
137	        HC_LOG("Failed to get wlan0 IP address");
138	    }
139	    
140	    int broadcast = 1;
141	    setsockopt(sockfd, SOL_SOCKET, SO_BROADCAST, &broadcast, sizeof(broadcast));
142	    
143	    memset(&broadcast_addr, 0, sizeof(broadcast_addr));
144	    broadcast_addr.sin_family = AF_INET;
145	    broadcast_addr.sin_addr.s_addr = INADDR_BROADCAST;
146	    broadcast_addr.sin_port = htons(DISCOVERY_PORT);
147	    
148	    ret = sendto(sockfd, DISCOVERY_MAGIC, strlen(DISCOVERY_MAGIC), 0,
149	                 (struct sockaddr *)&broadcast_addr, sizeof(broadcast_addr));
150	    if (ret < 0) {
151	        HC_LOG("Broadcast send failed");
152	        close(sockfd);
153	        g_server_discovered = false;
154	        return;
155	    }
156	    
157	    FD_ZERO(&readfds);
158	    FD_SET(sockfd, &readfds);
159	    timeout.tv_sec = DISCOVERY_TIMEOUT;
160	    timeout.tv_usec = 0;
161	    
162	    ret = select(sockfd + 1, &readfds, NULL, NULL, &timeout);
163	    if (ret <= 0) {
164	            HC_LOG("Discovery timeout or error");
165	        close(sockfd);
166	        g_server_discovered = false;
167	        return;
168	    }
169	    
170	    server_len = sizeof(server_addr);
171	    ret = recvfrom(sockfd, buffer, sizeof(buffer) - 1, 0,
172	                   (struct sockaddr *)&server_addr, &server_len);
173	    if (ret < 0) {
174	        HC_LOG("Receive response failed");
175	        close(sockfd);
176	        g_server_discovered = false;
177	        return;
178	    }
179	    
180	    buffer[ret] = '\0';
181	    
182	    if (strncmp(buffer, RESPONSE_MAGIC, strlen(RESPONSE_MAGIC)) == 0) {
183	        char *ip_start = buffer + strlen(RESPONSE_MAGIC) + 1;
184	        char *port_start = strchr(ip_start, ' ');
185	        
186	        if (port_start != NULL) {
187	            *port_start = '\0';
188	            port_start++;
189	            
190	            strncpy(g_server_ip, ip_start, sizeof(g_server_ip) - 1);
191	            g_server_port = atoi(port_start);
192	            g_server_discovered = true;
193	            
194	            HC_LOG("Server discovered: %s:%d", g_server_ip, g_server_port);
195	            close(sockfd);
196	            return;
197	        }
198	    }
199	    
200	    HC_LOG("Invalid response format");
201	    close(sockfd);
202	    g_server_discovered = false;
203	}
