205	static int send_control_command(int cmd)
206	{
207	    if (!g_server_discovered) {
208	            HC_LOG("Server not discovered, cannot send command");
209	        return -1;
210	    }
211	    
212	    int sock = socket(AF_INET, SOCK_STREAM, 0);
213	    if (sock < 0) {
214	        HC_LOG("Failed to create socket");
215	        return -1;
216	    }
217	    
218	    struct sockaddr_in server_addr;
219	    memset(&server_addr, 0, sizeof(server_addr));
220	    server_addr.sin_family = AF_INET;
221	    server_addr.sin_port = htons(g_server_port);
222	    inet_pton(AF_INET, g_server_ip, &server_addr.sin_addr);
223	    
224	    if (connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
225	        HC_LOG("Failed to connect to %s:%d", g_server_ip, g_server_port);
226	        close(sock);
227	        return -1;
228	    }
229	    
230	    char cmd_str[16] = {0};
231	    snprintf(cmd_str, sizeof(cmd_str), "%d", cmd);
232	    
233	    int ret = send(sock, cmd_str, strlen(cmd_str), 0);
234	    
235	    if (ret < 0) {
236	        HC_LOG("Failed to send command %d", cmd);
237	    } else {
238	        HC_LOG("Sent command %d to %s:%d", cmd, g_server_ip, g_server_port);
239	    }
240	    
241	    close(sock);
242	    return ret;
243	}
