297	int home_control_voice_execute(const char *text)
298	{
299	    if (!text || !text[0]) return HOME_CTRL_NONE;
300	
301	    /* 1. 解析动作 */
302	    int action = -1; /* -1=未知, 0=关, 1=开 */
303	    if (strstr_variants(text, ACT_ON)) {
304	        action = 1;
305	    } else if (strstr_variants(text, ACT_OFF)) {
306	        action = 0;
307	    }
308	    if (action < 0) return HOME_CTRL_NONE;
309	
310	    /* 2. 匹配设备 */
311	    int dev_index = -1;
312	    bool has_sub = false;
313	    for (int i = 0; i < (int)(sizeof(g_device_map) / sizeof(g_device_map[0])); i++) {
314	        if (strstr_variants(text, g_device_map[i].variants)) {
315	            dev_index = g_device_map[i].dev_index;
316	            has_sub = g_device_map[i].has_sub;
317	            break;
318	        }
319	    }
320	    if (dev_index < 0) {
321	        /* 有开关动作词但未匹配到设备：写标记文件供下一轮AI约束 */
322	        FILE *fp = fopen("/tmp/home_ctrl_nomatch", "w");
323	        if (fp) { fprintf(fp, "%s\n", text); fclose(fp); }
324	        return HOME_CTRL_NO_MATCH;
325	    }
326	
327	    /* 3. 确保设备列表已初始化 */
328	    init_devices();
329	
330	    HC_LOG("Voice cmd: %s → device[%d] %s → %s",
331	           text, dev_index, devices[dev_index].name,
332	           action ? "ON" : "OFF");
333	
334	    /* 4. 发现服务器 */
335	    if (!g_server_discovered) {
336	        discover_server_info();
337	    }
338	    if (!g_server_discovered) {
339	        HC_LOG("Server not discovered, cannot execute voice command");
340	        /* 写标记文件供下一轮AI约束 */
341	        FILE *fp = fopen("/tmp/home_ctrl_netfail", "w");
342	        if (fp) { fprintf(fp, "%s\n", devices[dev_index].name); fclose(fp); }
343	        return HOME_CTRL_NET_FAIL;
344	    }
345	
346	    /* 5. 计算命令码 */
347	    int cmd;
348	    if (has_sub) {
349	        cmd = action ? 23 : 24; /* 窗帘 */
350	    } else {
351	        cmd = action ? (dev_index * 2 + 1) : (dev_index * 2 + 2);
352	    }
353	
354	    /* 6. 发送指令 */
355	    int ret = send_control_command(cmd);
356	    if (ret < 0) {
357	        HC_LOG("Send command failed for device %s", devices[dev_index].name);
358	        /* 写标记文件供下一轮AI约束 */
359	        FILE *fp = fopen("/tmp/home_ctrl_netfail", "w");
360	        if (fp) { fprintf(fp, "%s\n", devices[dev_index].name); fclose(fp); }
361	        return HOME_CTRL_NET_FAIL;
362	    }
363	
364	    return HOME_CTRL_OK;
365	}
