544	static void switch_event_handler(lv_event_t *e)
545	{
546	    home_device_t *device = (home_device_t *)lv_event_get_user_data(e);
547	    lv_obj_t *switch_obj = lv_event_get_target(e);
548	    
549	    if (device) {
550	        bool is_on = lv_obj_has_state(switch_obj, LV_STATE_CHECKED);
551	        
552	        // 检查WiFi是否已连接
553	        if (!settings_wifi_is_connected()) {
554	            HC_LOG("WiFi not connected, please connect WiFi first");
555	            
556	            // 恢复开关状态
557	            if (is_on) {
558	                lv_obj_clear_state(switch_obj, LV_STATE_CHECKED);
559	            } else {
560	                lv_obj_add_state(switch_obj, LV_STATE_CHECKED);
561	            }
562	            
563	            // 显示提示信息
564	            lv_obj_t *msg_box = lv_obj_create(lv_scr_act());
565	            lv_obj_set_size(msg_box, 280, 80);
566	            lv_obj_set_style_bg_color(msg_box, lv_color_hex(0x333333), 0);
567	            lv_obj_set_style_border_width(msg_box, 2, 0);
568	            lv_obj_set_style_border_color(msg_box, lv_color_hex(0xFF5722), 0);
569	            lv_obj_set_style_radius(msg_box, 10, 0);
570	            lv_obj_align(msg_box, LV_ALIGN_CENTER, 0, 0);
571	            
572	            lv_obj_t *msg_label = lv_label_create(msg_box);
573	            lv_label_set_text(msg_label, "请先连接WiFi");
574	            lv_obj_set_style_text_color(msg_label, lv_color_white(), 0);
575	            lv_obj_set_style_text_font(msg_label, vw_resource_get_font(WATCH_REGULAR_FONT "_24"), 0);
576	            lv_obj_align(msg_label, LV_ALIGN_CENTER, 0, -10);
577	            
578	            lv_obj_t *hint_label = lv_label_create(msg_box);
579	            lv_label_set_text(hint_label, "请前往设置连接WiFi");
580	            lv_obj_set_style_text_color(hint_label, lv_color_hex(0xAAAAAA), 0);
581	            lv_obj_set_style_text_font(hint_label, vw_resource_get_font(WATCH_REGULAR_FONT "_16"), 0);
582	            lv_obj_align(hint_label, LV_ALIGN_CENTER, 0, 15);
583	            
584	            // 3秒后自动关闭提示框
585	            lv_timer_create(msg_box_timer_cb, 3000, msg_box);
586	            
587	            return;
588	        }
589	        
590	        device->status = is_on;
591	        HC_LOG("Device: %s, status: %s", device->name, is_on ? "ON" : "OFF");
592	        
593	        if (!g_server_discovered) {
594	            HC_LOG("Server not discovered, discovering...");
595	            discover_server_info();
596	        }
597	        
598	        int cmd = is_on ? 1 : 2;
599	        
600	        if (device->has_sub_switch) {
601	            cmd = is_on ? 23 : 24;  // 窗帘电源：上电23，关闭电源24
602	        } else {
603	            for (int i = 0; i < DEVICE_COUNT; i++) {
604	                if (strcmp(device->name, devices[i].name) == 0) {
605	                    cmd = is_on ? (i * 2 + 1) : (i * 2 + 2);
606	                    break;
607	                }
608	            }
609	        }
610	        
611	        HC_LOG("Sending command %d for device %s", cmd, device->name);
612	        send_control_command(cmd);
613	    }
614	}
