618	 */
619	static void slide_gesture_handler(lv_event_t *e)
620	{
621	    lv_event_code_t code = lv_event_get_code(e);
622	    static lv_point_t start_point = {0};
623	
624	    switch(code) {
625	        case LV_EVENT_PRESSED:
626	            HC_LOG("home_control: pressed");
627	            lv_indev_get_point(lv_indev_active(), &start_point);
628	            break;
629	        
630	        case LV_EVENT_RELEASED:
631	        {
632	            lv_point_t end_point;
633	            lv_indev_get_point(lv_indev_active(), &end_point);
634	            
635	            int32_t delta_x = end_point.x - start_point.x;
636	            int32_t delta_y = end_point.y - start_point.y;
637	
638	            HC_LOG("home_control: released, delta_x=%d, delta_y=%d", delta_x, delta_y);
639	
640	            // 右滑退出（横向移动超过50px且大于纵向移动）
641	            if(delta_x > 50 && abs(delta_x) > abs(delta_y)) {
642	                HC_LOG("home_control: right swipe, exit");
643	                if(home_control_base != NULL) {
644	                    // 将页面从页面栈弹出
645	                    vw_watch_pop_page(home_control_base);
646	                    lv_obj_del(home_control_base);
647	                    home_control_base = NULL;
648	                }
649	            }
650	            break;
651	        }
652	        default:
653	            break;
654	    }
655	}
