167	        if (skill_sync_from_bitable() != OK) {
168	            syslog(LOG_WARNING, "[%s] Bitable skill sync failed, using local skills\n", TAG);
169	        }
170	#endif
171	
172	#ifdef CONFIG_AI_AGENT_FEISHU
173	        if (feishu_bot_start() != OK)
174	            syslog(LOG_WARNING, "[%s] feishu_bot_start failed\n", TAG);
175	#endif
176	        if (agent_loop_start() != OK)
177	            syslog(LOG_WARNING, "[%s] agent_loop_start failed\n", TAG);
178	        if (ws_server_start() != OK)
179	            syslog(LOG_WARNING, "[%s] ws_server_start failed\n", TAG);
180	#ifdef CONFIG_AI_AGENT_NODE
181	        if (node_client_start() != OK)
182	            syslog(LOG_WARNING, "[%s] node_client_start failed\n", TAG);
183	#endif
184	#ifdef CONFIG_AI_AGENT_MQTT
185	        if (mqtt_channel_start() != OK)
186	            syslog(LOG_WARNING, "[%s] mqtt_channel_start failed\n", TAG);
187	#endif
188	#ifdef CONFIG_AI_AGENT_WEIXIN
189	        if (weixin_channel_start() != OK)
190	            syslog(LOG_WARNING, "[%s] weixin_channel_start failed\n", TAG);
191	#endif
192	
193	        syslog(LOG_INFO, "[%s] All network services started!\n", TAG);
194	
195	        /* Auto mode: voice_channel_start_wake() is called externally
196	         * by the launcher after both agent init and WiFi are confirmed
197	         * ready. This avoids race conditions where the conversation
198	         * thread starts before the network is stable. */
199	
200	#ifdef CONFIG_AI_AGENT_NET_RPMSG
201	        g_net_services_started = true;
202	#endif
203	    } else {
204	        syslog(LOG_WARNING, "[%s] Network timeout — net services not started.\n", TAG);
205	        syslog(LOG_WARNING, "[%s] Use 'config_show' / 'set_*' CLI commands to configure.\n", TAG);
206	        /* Play no-network alert audio (highest priority) */
