211	    /* Register listener for network state changes — auto-restart services on reconnect */
212	    network_register_listener(net_state_change_cb, NULL);
213	
214	    /* Keep thread alive to handle reconnection events */
215	    while (!g_shutdown_requested) {
216	        sleep(1);
217	    }
218	#endif
219	
220	    return NULL;
221	}
