230	#define VELACLAW_MQ_QAPP_IN   "/velaclaw_qapp_in"
231	#define VELACLAW_MQ_QAPP_OUT  "/velaclaw_qapp_out"
232	#define VELACLAW_MQ_MSG_SIZE  4096
233	#define VELACLAW_MQ_MAX_MSGS  4
234	
235	/**
236	 * Reads requests from the quickapp process via POSIX mqueue and feeds
237	 * them into the local message_bus inbound queue.
238	 */
239	static void *quickapp_mq_listener_task(void *arg)
240	{
241	    (void)arg;
242	    syslog(LOG_INFO, "[%s] Quickapp mqueue listener started\n", TAG);
243	
244	    struct mq_attr attr = {
245	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
246	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
247	    };
248	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_IN, O_RDONLY | O_CREAT, 0666, &attr);
249	    if (mq == (mqd_t)-1) {
250	        syslog(LOG_ERR, "[%s] Failed to open quickapp inbound mqueue: %d\n", TAG, errno);
251	        return NULL;
252	    }
253	
254	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
255	    if (!buf) {
256	        syslog(LOG_ERR, "[%s] Failed to allocate mqueue recv buffer\n", TAG);
257	        mq_close(mq);
258	        return NULL;
259	    }
260	
261	    while (1) {
262	        ssize_t n = mq_receive(mq, buf, VELACLAW_MQ_MSG_SIZE, NULL);
263	        if (n < 0) {
264	            if (errno == EINTR) continue;
265	            syslog(LOG_ERR, "[%s] mq_receive failed: %d\n", TAG, errno);
266	            break;
267	        }
268	        if (n >= (ssize_t)VELACLAW_MQ_MSG_SIZE) {
269	            n = VELACLAW_MQ_MSG_SIZE - 1;
270	        }
271	        buf[n] = '\0';
272	
273	        /* Message format: "chat_id\nquery" */
274	        char *sep = strchr(buf, '\n');
275	        if (!sep) {
276	            syslog(LOG_WARNING, "[%s] Malformed quickapp message\n", TAG);
277	            continue;
278	        }
279	        *sep = '\0';
280	        const char *chat_id = buf;
281	        const char *query = sep + 1;
282	
283	        syslog(LOG_INFO, "[%s] Quickapp request: chat_id=%s query=%.40s\n",
284	               TAG, chat_id, query);
285	
286	        agent_msg_t msg = {0};
287	        strncpy(msg.channel, AGENT_CHAN_QUICKAPP, sizeof(msg.channel) - 1);
288	        strncpy(msg.chat_id, chat_id, sizeof(msg.chat_id) - 1);
289	        msg.content = strdup(query);
290	        if (msg.content) {
291	            message_bus_push_inbound(&msg);
292	        }
293	    }
294	
295	    free(buf);
296	    mq_close(mq);
297	    return NULL;
298	}
