304	static void quickapp_mq_dispatch(const char *chat_id, const char *content)
305	{
306	    struct mq_attr attr = {
307	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
308	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
309	    };
310	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_OUT, O_WRONLY | O_CREAT, 0666, &attr);
311	    if (mq == (mqd_t)-1) {
312	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_open failed: %d\n", TAG, errno);
313	        return;
314	    }
315	
316	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
317	    if (!buf) {
318	        mq_close(mq);
319	        return;
320	    }
321	    int len = snprintf(buf, VELACLAW_MQ_MSG_SIZE, "%s\n%s", chat_id, content);
322	    if (len >= (int)VELACLAW_MQ_MSG_SIZE) {
323	        len = VELACLAW_MQ_MSG_SIZE - 1;
324	        buf[len] = '\0';
325	    }
326	
327	    if (mq_send(mq, buf, len + 1, 0) != 0) {
328	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_send failed: %d\n", TAG, errno);
329	    } else {
330	        syslog(LOG_INFO, "[%s] quickapp dispatch: reply sent chat_id=%s\n", TAG, chat_id);
331	    }
332	    free(buf);
333	    mq_close(mq);
334	}
