390	            ws_server_send(msg.chat_id, msg.content);
391	#ifdef CONFIG_AI_AGENT_MQTT
392	        } else if (strcmp(msg.channel, AGENT_CHAN_MQTT) == 0) {
393	            mqtt_channel_send(msg.chat_id, msg.content);
394	#endif
395	        } else if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
396	            /* TTS already handled in dispatch_response (agent_loop.c).
397	             * Voice channel outbound dispatch is a no-op — the response
398	             * was already spoken before being enqueued. */
399	#ifdef CONFIG_AI_AGENT_LVGL_UI
400	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) == 0) {
401	            int uret = lvgl_ui_channel_send(msg.content);
402	            if (uret != 0) {
403	                syslog(LOG_ERR, "[%s] lvgl_ui_channel_send failed: %d\n", TAG, uret);
404	            }
405	#endif
406	#ifdef CONFIG_AI_AGENT_WEIXIN
407	        } else if (strcmp(msg.channel, AGENT_CHAN_WEIXIN) == 0) {
408	            /* chat_id format: "from_user_id|context_token" */
409	            char uid[64] = "";
410	            const char* ctx = "";
411	            char* sep = strchr(msg.chat_id, '|');
412	            if (sep) {
413	                size_t ulen = (size_t)(sep - msg.chat_id);
414	                if (ulen >= sizeof(uid))
415	                    ulen = sizeof(uid) - 1;
416	                memcpy(uid, msg.chat_id, ulen);
417	                uid[ulen] = '\0';
418	                ctx = sep + 1;
419	            } else {
420	                strncpy(uid, msg.chat_id, sizeof(uid) - 1);
421	            }
422	            weixin_channel_send(uid, ctx, msg.content);
423	#endif
424	        } else if (strcmp(msg.channel, AGENT_CHAN_SYSTEM) == 0) {
425	            syslog(LOG_INFO, "[%s] System message [%s]: %.128s\n", TAG, msg.chat_id, msg.content);
426	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
427	        } else if (strcmp(msg.channel, AGENT_CHAN_QUICKAPP) == 0) {
428	            quickapp_mq_dispatch(msg.chat_id, msg.content);
429	#endif
430	        } else if (strcmp(msg.channel, "cli") == 0) {
431	            pthread_mutex_lock(&g_stdout_lock);
432	            syslog("\n[Agent]: %s\nvela> ", msg.content);
433	            fflush(stdout);
434	            pthread_mutex_unlock(&g_stdout_lock);
435	            syslog(LOG_INFO, "[agent] [Agent]: %s\n", msg.content);
436	        } else {
437	            syslog(LOG_WARNING, "[%s] Unknown channel: %s\n", TAG, msg.channel);
438	        }
439	
440	        free(msg.content);
441	    }
442	
443	    syslog(LOG_INFO, "[%s] Outbound dispatch exiting\n", TAG);
444	    return NULL;
445	}
