449	/* ── Startup timing helpers ───────────────────────────────────── */
450	
451	static inline long boot_ms(struct timespec* t0)
452	{
453	    struct timespec now;
454	    clock_gettime(CLOCK_MONOTONIC, &now);
455	    return (long)((now.tv_sec - t0->tv_sec) * 1000L + (now.tv_nsec - t0->tv_nsec) / 1000000L);
456	}
457	
458	#define BOOT_LOG(t0, phase, msg) \
459	    syslog(LOG_INFO, "[%s] [boot +%ldms] " phase ": " msg "\n", TAG, boot_ms(t0))
460	
461	#define BOOT_LOG_RC(t0, phase, msg, rc) \
462	    syslog((rc) == OK ? LOG_INFO : LOG_WARNING, \
463	        "[%s] [boot +%ldms] " phase ": " msg " (rc=%d)\n", TAG, boot_ms(t0), (rc))
464	
465	int ai_agent_main(int argc, char* argv[])
466	{
467	    /* "auto" argv: launched from launcher at boot — no CLI thread,
468	     * auto wake-word listening after network is up. */
469	    g_auto_voice = false;
470	    for (int i = 1; i < argc; i++) {
471	        if (argv[i] && strcmp(argv[i], "auto") == 0) {
472	            g_auto_voice = true;
473	        }
474	    }
475	
476	    g_shutdown_requested = false;
477	
478	    struct timespec t0;
479	    clock_gettime(CLOCK_MONOTONIC, &t0);
480	
481	    syslog(LOG_INFO, "[%s] AI Agent - Vela AI Agent starting (build: %s)\n",
482	        TAG, AGENT_BUILD_VERSION);
483	
484	    /* ── Phase 0: Timezone ──────────────────────────────────── */
485	    /* Set TZ before any time calls so localtime_r returns CST+8.
486	     * NuttX with CONFIG_LIBC_LOCALTIME+CONFIG_LIBC_ZONEINFO supports
487	     * both POSIX ("CST-8") and zoneinfo ("Asia/Shanghai") formats. */
488	    setenv("TZ", AGENT_TIMEZONE, 1);
489	#ifdef CONFIG_LIBC_LOCALTIME
490	    tzset();
491	#endif
492	    BOOT_LOG(&t0, "P0", "timezone set");
493	
494	    /* ── Phase 0: Storage Bootstrapping (Auto-mount & Mkdir) ── */
495	
496	    struct stat st;
497	    if (stat("/data", &st) != 0) {
498	        syslog(LOG_INFO, "[%s] Mounting /data as tmpfs for simulation...\n", TAG);
499	        mount(NULL, "/data", "tmpfs", 0, NULL);
500	    }
501	
502	    /* Ensure directory structure exists (use configured AGENT_DATA_DIR) */
503	    mkdir(AGENT_DATA_DIR, 0755);
504	    mkdir(AGENT_CONFIG_DIR, 0755);
505	    mkdir(AGENT_MEMORY_DIR, 0755);
506	    mkdir(AGENT_SESSION_DIR, 0755);
507	    mkdir(AGENT_SKILLS_DIR, 0755);
508	
509	    /* Restore persistent config from SPI Flash (survives reboot).
510	     * Only config.json is persisted — skills/memory/sessions are
511	     * rebuilt at runtime on fast tmpfs. */
512	    {
513	        struct stat ps;
514	        if (stat(AGENT_PERSIST_CONFIG_FILE, &ps) == 0 && ps.st_size > 0) {
515	            /* Copy SPI Flash → tmpfs */
516	            char buf[1024];
517	            int src = open(AGENT_PERSIST_CONFIG_FILE, O_RDONLY);
518	            if (src >= 0) {
519	                int dst = open(AGENT_CONFIG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
520	                if (dst >= 0) {
521	                    ssize_t n;
522	                    while ((n = read(src, buf, sizeof(buf))) > 0) {
523	                        write(dst, buf, (size_t)n);
524	                    }
525	                    close(dst);
526	                }
527	                close(src);
528	                syslog(LOG_INFO, "[%s] Restored config from %s\n",
529	                    TAG, AGENT_PERSIST_CONFIG_FILE);
530	            }
531	        } else {
532	            /* Ensure SPI Flash persist dir exists for later writes */
533	            mkdir("/mnt/spif/ai_agent", 0755);
534	            mkdir(AGENT_PERSIST_CONFIG_DIR, 0755);
535	        }
536	    }
537	    BOOT_LOG(&t0, "P0", "storage ready");
538	
539	    /* Memory info */
540	    {
541	        struct mallinfo mi = mallinfo();
542	        syslog(LOG_INFO, "[%s] [boot +%ldms] heap: arena=%d free=%d used=%d\n",
543	            TAG, boot_ms(&t0), mi.arena, mi.fordblks, mi.uordblks);
544	    }
545	
546	    /* ── Phase 1: Core infrastructure ──────────────────────── */
547	    {
548	        int rc;
549	        rc = config_store_init();
550	        BOOT_LOG_RC(&t0, "P1", "config_store_init", rc);
551	
552	        rc = message_bus_init();
553	        BOOT_LOG_RC(&t0, "P1", "message_bus_init", rc);
554	        if (rc != OK)
555	            return -1;
556	
557	        rc = memory_store_init();
558	        BOOT_LOG_RC(&t0, "P1", "memory_store_init", rc);
559	
560	        rc = session_mgr_init();
561	        BOOT_LOG_RC(&t0, "P1", "session_mgr_init", rc);
562	    }
563	
564	    /* ── Phase 2: Proxy / networking ───────────────────────── */
565	    {
566	        int rc = http_proxy_init();
567	        BOOT_LOG_RC(&t0, "P2", "http_proxy_init", rc);
568	    }
569	
570	    /* ── Phase 3: Application services ─────────────────────── */
571	    {
572	        int rc;
573	#ifdef CONFIG_AI_AGENT_FEISHU
574	        rc = feishu_bot_init();
575	        BOOT_LOG_RC(&t0, "P3", "feishu_bot_init", rc);
576	#endif
577	
578	        rc = llm_proxy_init();
579	        BOOT_LOG_RC(&t0, "P3", "llm_proxy_init", rc);
580	
581	        rc = llm_router_init();
582	        BOOT_LOG_RC(&t0, "P3", "llm_router_init", rc);
583	
584	        /* node_manager must init BEFORE tool_registry so it can
585	         * register itself as a tool provider. */
586	#ifdef CONFIG_AI_AGENT_NODE
587	        rc = node_manager_init();
588	        BOOT_LOG_RC(&t0, "P3", "node_manager_init", rc);
589	#endif
590	
591	        rc = tool_registry_init();
592	        BOOT_LOG_RC(&t0, "P3", "tool_registry_init", rc);
593	
594	        rc = tool_guard_init();
595	        BOOT_LOG_RC(&t0, "P3", "tool_guard_init", rc);
596	
597	        /* Skills must init AFTER tool_registry so executable skills
598	         * can register themselves as tools. */
599	        rc = skill_loader_init();
600	        BOOT_LOG_RC(&t0, "P3", "skill_loader_init", rc);
601	
602	        rc = agent_loop_init();
603	        BOOT_LOG_RC(&t0, "P3", "agent_loop_init", rc);
604	
605	        rc = cron_service_init();
606	        BOOT_LOG_RC(&t0, "P3", "cron_service_init", rc);
607	
608	        rc = heartbeat_init();
609	        BOOT_LOG_RC(&t0, "P3", "heartbeat_init", rc);
610	
611	#ifdef CONFIG_AI_AGENT_NODE
612	        rc = node_client_init();
613	        BOOT_LOG_RC(&t0, "P3", "node_client_init", rc);
614	#endif
615	
616	#ifdef CONFIG_AI_AGENT_MQTT
617	        rc = mqtt_channel_init();
618	        BOOT_LOG_RC(&t0, "P3", "mqtt_channel_init", rc);
619	#endif
620	
621	        rc = voice_channel_init();
622	        BOOT_LOG_RC(&t0, "P3", "voice_channel_init", rc);
623	
624	#ifdef CONFIG_AI_AGENT_WEIXIN
625	        rc = weixin_channel_init();
626	        BOOT_LOG_RC(&t0, "P3", "weixin_channel_init", rc);
627	#endif
628	
629	#ifdef CONFIG_AI_AGENT_LVGL_UI
630	        rc = lvgl_ui_channel_init();
631	        BOOT_LOG_RC(&t0, "P3", "lvgl_ui_channel_init", rc);
632	#endif
633	    }
634	
635	    /* ── Phase 4: CLI — register commands only, no thread yet ── */
636	    {
637	        int rc = nsh_commands_init();
638	        BOOT_LOG_RC(&t0, "P4", "nsh_commands_init", rc);
639	    }
640	
641	    /* ── Phase 5: Network — async, does NOT block ready ────── */
642	
643	    /* Kick off WiFi reconnect and start outbound dispatch immediately.
644	     * Network-dependent services (feishu, agent, ws, node) are started
645	     * inside the network_watch thread once the link comes up. */
646	
647	    /* Outbound dispatch thread — start before network so queued messages
648	     * are drained even during the connection window. */
649	    if (agent_task_create(outbound_dispatch_task, "outbound",
650	            AGENT_OUTBOUND_STACK, NULL,
651	            AGENT_OUTBOUND_PRIO)
652	        != OK) {
653	        syslog(LOG_ERR, "[%s] Failed to start outbound dispatch thread\n", TAG);
654	        return -1;
655	    }
656	    BOOT_LOG(&t0, "P5", "outbound dispatch thread started");
657	
658	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
659	    /* Quickapp mqueue listener - receives requests from quickapp process */
660	    if (agent_task_create(quickapp_mq_listener_task, "qapp_mq",
661	                         AGENT_OUTBOUND_STACK, NULL,
662	                         AGENT_OUTBOUND_PRIO) != OK) {
663	        syslog(LOG_WARNING, "[%s] Failed to start quickapp mqueue listener\n", TAG);
664	    }
665	    BOOT_LOG(&t0, "P5", "quickapp mqueue listener started");
666	#endif
667	
668	    /* Cron + heartbeat don't need network */
669	    cron_service_start();
670	    heartbeat_start();
671	    BOOT_LOG(&t0, "P5", "cron + heartbeat started");
672	
673	#ifdef CONFIG_AI_AGENT_LVGL_UI
674	    if (lvgl_ui_channel_start() != OK)
675	        syslog(LOG_WARNING, "[%s] lvgl_ui_channel_start failed\n", TAG);
676	    BOOT_LOG(&t0, "P5", "lvgl_ui_channel started");
677	#endif
678	
679	#ifdef CONFIG_AI_AGENT_BLE_GATT
680	    /* BLE GATT: ensure adapter enabled, then init with retries */
681	    {
682	        extern void ble_cmd_handler_recv(const uint8_t* data, uint16_t len,
683	            void* user_data);
684	        bt_instance_t* bt_ins = bluetooth_get_instance();
685	        if (bt_ins) {
686	            bt_adapter_state_t state = bt_adapter_get_state(bt_ins);
687	            if (state < BT_ADAPTER_STATE_BLE_ON) {
688	                syslog(LOG_INFO, "[%s] BT not ready (state=%d), enabling LE...\n",
689	                    TAG, (int)state);
690	                bt_adapter_enable_le(bt_ins);
691	                sleep(2);
692	            }
693	        }
694	
695	        ble_gatt_config_t ble_cfg = {
696	            .device_name = "VelaClaw",
697	            .recv_cb = ble_cmd_handler_recv,
698	        };
699	        int rc = -1;
700	        int attempts = 0;
701	        while (rc < 0 && attempts < 5) {
702	            rc = ble_gatt_init(&ble_cfg);
703	            if (rc < 0) {
704	                syslog(LOG_WARNING, "[%s] ble_gatt_init attempt %d failed: %d\n",
705	                    TAG, attempts + 1, rc);
706	                sleep(3);
707	            }
708	            attempts++;
709	        }
710	        if (rc == 0) {
711	            BOOT_LOG(&t0, "P5", "ble_gatt init OK");
712	        } else {
713	            BOOT_LOG(&t0, "P5", "ble_gatt FAILED after retries");
714	        }
715	    }
716	#endif
717	
718	    /* Network watcher thread: reconnect + wait + start net services */
719	    if (agent_task_create(network_watch_task, "net_watch",
720	            AGENT_OUTBOUND_STACK, NULL,
721	            AGENT_OUTBOUND_PRIO)
722	        != OK) {
723	        syslog(LOG_WARNING, "[%s] Failed to start network_watch thread\n", TAG);
724	    }
725	    BOOT_LOG(&t0, "P5", "network_watch thread started (async)");
726	
727	    /* ── Phase 6: CLI thread — all services now in known state ── */
728	    if (!g_auto_voice) {
729	        int rc = nsh_commands_start();
730	        BOOT_LOG_RC(&t0, "P6", "nsh_commands_start", rc);
731	    } else {
732	        /* Auto mode: skip CLI — cli_thread reads stdin and would
733	         * fight the NSH console for input. */
734	        BOOT_LOG(&t0, "P6", "CLI skipped (auto mode)");
735	    }
736	
737	    syslog(LOG_INFO, "[%s] [boot +%ldms] AI Agent ready. Type 'help' in NSH for commands.\n",
738	        TAG, boot_ms(&t0));
739	
740	    /* Block main thread until shutdown is requested */
741	    while (!g_shutdown_requested) {
742	        sleep(1);
743	    }
744	
745	    syslog(LOG_INFO, "[%s] Shutdown requested — stopping services...\n", TAG);
746	
747	    /* Wake all threads blocked on message bus before stopping services */
748	    message_bus_wakeup();
749	
750	    /* ── Graceful teardown (reverse of startup order) ──────── */
751	
752	    /* Phase 5 services (network-dependent) */
753	#ifdef CONFIG_AI_AGENT_WEIXIN
754	    weixin_channel_stop();
755	#endif
756	#ifdef CONFIG_AI_AGENT_NODE
757	    node_client_stop();
758	#endif
759	#ifdef CONFIG_AI_AGENT_MQTT
760	    mqtt_channel_stop();
761	#endif
762	    ws_server_stop();
763	    /* feishu_bot and agent_loop have no _stop(); they will exit
764	     * naturally once their blocking I/O returns an error after
765	     * the network sockets are closed below, or they can check
766	     * agent_shutdown_requested() in their loops. */
767	
768	#ifdef CONFIG_AI_AGENT_LVGL_UI
769	    lvgl_ui_channel_stop();
770	#endif
771	
772	    /* Phase 5 services (non-network) */
773	    cron_service_stop();
774	    heartbeat_stop();
775	
776	    /* Give threads a moment to notice and exit */
777	    usleep(500 * 1000);
778	
779	    /* Cleanup — reverse order of init */
780	    tool_media_cleanup();
781	#ifdef CONFIG_AI_AGENT_MCP
782	    mcp_bridge_cleanup();
783	#endif
784	    tool_guard_cleanup();
785	    tool_registry_cleanup();
786	    llm_cache_cleanup();
787	    vela_tls_pool_cleanup();
788	    message_bus_destroy();
789	
790	    syslog(LOG_INFO, "[%s] Shutdown complete.\n", TAG);
791	
792	    return 0;
793	}
