25	#define VOICE_ASR_MAX_BACKENDS 4
26	
27	static const char* TAG = "voice_asr";
28	
29	static const voice_asr_ops_t* s_backends[VOICE_ASR_MAX_BACKENDS];
30	static int s_backend_count;
31	static const voice_asr_ops_t* s_active;
32	
33	int voice_asr_register(const voice_asr_ops_t* ops)
34	{
35	    if (!ops || !ops->name || !ops->recognize) {
36	        return -EINVAL;
37	    }
38	
39	    if (s_backend_count >= VOICE_ASR_MAX_BACKENDS) {
40	        syslog(LOG_ERR, "[%s] Too many ASR backends\n", TAG);
41	        return -ENOMEM;
42	    }
43	
44	    s_backends[s_backend_count++] = ops;
45	    syslog(LOG_INFO, "[%s] Registered backend: %s\n", TAG, ops->name);
46	
47	    /* First registered backend becomes the default */
48	    if (!s_active) {
49	        s_active = ops;
50	        if (ops->init) {
51	            ops->init();
52	        }
53	    }
54	
55	    return 0;
56	}
57	
58	int voice_asr_set_backend(const char* name)
59	{
60	    if (!name) {
61	        return -EINVAL;
62	    }
63	
64	    for (int i = 0; i < s_backend_count; i++) {
65	        if (strcmp(s_backends[i]->name, name) == 0) {
66	            if (s_active && s_active->deinit) {
67	                s_active->deinit();
68	            }
69	
70	            s_active = s_backends[i];
71	            if (s_active->init) {
72	                s_active->init();
73	            }
74	
75	            syslog(LOG_INFO, "[%s] Backend set to: %s\n",
76	                TAG, name);
77	            return 0;
78	        }
79	    }
80	
81	    syslog(LOG_ERR, "[%s] Backend not found: %s\n", TAG, name);
82	    return -ENOENT;
83	}
84	
85	const char* voice_asr_get_backend(void)
86	{
87	    return s_active ? s_active->name : NULL;
88	}
89	
90	int voice_asr_recognize(const unsigned char* pcm_data,
91	    size_t pcm_len,
92	    char* text_out,
93	    size_t text_cap)
94	{
95	    if (!s_active) {
96	        syslog(LOG_ERR, "[%s] No ASR backend registered\n", TAG);
97	        return -ENODEV;
98	    }
99	
100	    return s_active->recognize(pcm_data, pcm_len, text_out, text_cap);
101	}
102	
103	/* ── Streaming ASR ───────────────────────────────────────────────
104	 * Dispatches to the active backend's stream_* vtable when present.
105	 * Backends without streaming support (volc_asr, mimo_asr) keep using
106	 * the legacy volc_asr streaming path, so behaviour is unchanged. */
107	
108	struct voice_asr_stream {
109	    const voice_asr_ops_t* ops; /* non-NULL: vtable path */
110	    void* ext;                  /* backend-private handle (vtable path) */
111	    volc_asr_stream_t* inner;   /* legacy path */
112	};
113	
114	voice_asr_stream_t* voice_asr_stream_open(void)
115	{
116	    if (!s_active) {
117	        syslog(LOG_ERR, "[%s] No ASR backend for streaming\n", TAG);
118	        return NULL;
119	    }
120	
121	    voice_asr_stream_t* s = calloc(1, sizeof(*s));
122	
123	    if (!s) {
124	        return NULL;
125	    }
126	
127	    if (s_active->stream_open) {
128	        void* ext = NULL;
129	        int ret = s_active->stream_open(&ext);
130	
131	        if (ret != 0) {
132	            syslog(LOG_ERR, "[%s] %s stream_open failed: %d\n",
133	                TAG, s_active->name, ret);
134	            free(s);
135	            return NULL;
136	        }
137	
138	        s->ops = s_active;
139	        s->ext = ext;
140	        return s;
141	    }
142	
143	    volc_asr_stream_t* inner = volc_asr_stream_open();
144	
145	    if (!inner) {
146	        free(s);
147	        return NULL;
148	    }
149	
150	    s->inner = inner;
151	    return s;
152	}
153	
154	int voice_asr_stream_send(voice_asr_stream_t* s,
155	    const unsigned char* pcm, size_t len)
156	{
157	    if (!s) {
158	        return -EINVAL;
159	    }
160	
161	    if (s->ops) {
162	        if (!s->ops->stream_send) return -ENOSYS;
163	        return s->ops->stream_send(s->ext, pcm, len);
164	    }
165	
166	    if (!s->inner) {
167	        return -EINVAL;
168	    }
169	
170	    return volc_asr_stream_send(s->inner, pcm, len);
171	}
172	
173	int voice_asr_stream_finish(voice_asr_stream_t* s,
174	    char* text_out, size_t text_cap)
175	{
176	    if (!s) {
177	        return -EINVAL;
178	    }
179	
180	    if (s->ops) {
181	        int ret = s->ops->stream_finish
182	            ? s->ops->stream_finish(s->ext, text_out, text_cap)
183	            : -ENOSYS;
184	        free(s);
185	        return ret;
186	    }
187	
