209	void voice_asr_stream_abort(voice_asr_stream_t* s)
210	{
211	    if (!s) {
212	        return;
213	    }
214	
215	    if (s->ops) {
216	        if (s->ops->stream_abort) {
217	            s->ops->stream_abort(s->ext);
218	        }
219	        free(s);
220	        return;
221	    }
222	
223	    volc_asr_stream_abort(s->inner);
