33	int voice_tts_register(const voice_tts_ops_t* ops)
34	{
35	    if (!ops || !ops->name || (!ops->synthesize && !ops->synthesize_stream)) {
36	        return -EINVAL;
37	    }
38	
39	    if (s_backend_count >= VOICE_TTS_MAX_BACKENDS) {
40	        syslog(LOG_ERR, "[%s] Too many TTS backends\n", TAG);
41	        return -ENOMEM;
42	    }
43	
44	    s_backends[s_backend_count++] = ops;
45	    syslog(LOG_INFO, "[%s] Registered backend: %s\n", TAG, ops->name);
46	
47	    /* First registered backend becomes the default */
48	    if (!s_active) {
49	        s_active = ops;
50	        if (ops->init) {
51	            ops->init();
52	        }
53	    }
54	
55	    return 0;
56	}
