58	int voice_tts_set_backend(const char* name)
59	{
60	    if (!name) {
61	        return -EINVAL;
62	    }
63	
64	    syslog(LOG_INFO, "[%s] set_backend: looking for '%s' among %d backends\n",
65	        TAG, name, s_backend_count);
66	
67	    for (int i = 0; i < s_backend_count; i++) {
68	        syslog(LOG_INFO, "[%s]   backend[%d]: '%s'\n",
69	            TAG, i, s_backends[i]->name);
70	        if (strcmp(s_backends[i]->name, name) == 0) {
71	            if (s_active && s_active->deinit) {
72	                s_active->deinit();
73	            }
74	
75	            s_active = s_backends[i];
76	            if (s_active->init) {
77	                int rc = s_active->init();
78	                syslog(LOG_INFO, "[%s] init('%s') rc=%d\n",
79	                    TAG, name, rc);
80	            }
81	
82	            syslog(LOG_INFO, "[%s] Backend set to: %s\n",
83	                TAG, name);
84	            return 0;
85	        }
86	    }
87	
88	    syslog(LOG_ERR, "[%s] Backend not found: %s\n", TAG, name);
89	    return -ENOENT;
90	}
