111	
112	int voice_tts_speak_stream(const char* text,
113	    voice_tts_chunk_cb cb,
114	    void* user_data)
115	{
116	    if (!s_active) {
117	        syslog(LOG_ERR, "[%s] No TTS backend for streaming\n", TAG);
118	        return -ENODEV;
119	    }
120	
121	    /* Use backend's streaming method if available */
122	    if (s_active->synthesize_stream) {
123	        return s_active->synthesize_stream(text, cb, user_data);
124	    }
125	
126	    /* Fallback: batch synthesize, then deliver as one chunk */
127	    unsigned char* pcm = malloc(AGENT_VOICE_PCM_BUF_SIZE);
128	    if (!pcm) return -ENOMEM;
129	
130	    size_t pcm_len = 0;
131	    int ret = s_active->synthesize(text, pcm, AGENT_VOICE_PCM_BUF_SIZE, &pcm_len);
132	    if (ret == 0 && pcm_len > 0) {
133	        cb(pcm, pcm_len, 0, user_data);
134	        cb(NULL, 0, 1, user_data);
135	    }
136	    free(pcm);
137	    return ret;
138	}
