181	static void preproc_chunk(audio_preproc_t* pp,
182	    unsigned char* buf, int bytes)
183	{
184	    if (!pp || (!pp->ns && !pp->agc)) {
185	        return;
186	    }
187	
188	    int16_t* samples = (int16_t*)buf;
189	    int total = bytes / 2;
190	    int fsz = PREPROC_FRAME_SIZE;
191	    int32_t in32[PREPROC_FRAME_SIZE];
192	    int32_t ref32[PREPROC_FRAME_SIZE];
193	    int32_t out32[PREPROC_FRAME_SIZE];
194	
195	    memset(ref32, 0, sizeof(ref32));
196	
197	    for (int off = 0; off < total; off += fsz) {
198	        int n = (off + fsz <= total) ? fsz : (total - off);
199	
200	        for (int i = 0; i < n; i++) {
201	            in32[i] = samples[off + i];
202	        }
203	
204	        if (pp->ns) {
205	            ec2float_process(pp->ns, in32, ref32, n, out32);
206	        } else {
207	            memcpy(out32, in32, n * sizeof(int32_t));
208	        }
209	
210	        if (pp->agc) {
211	            for (int i = 0; i < n; i++) {
212	                out32[i] <<= 8;
213	            }
214	            compexp_process_int24(pp->agc, out32, n);
215	            for (int i = 0; i < n; i++) {
216	                out32[i] >>= 8;
217	            }
218	        }
219	
220	        for (int i = 0; i < n; i++) {
221	            int32_t v = out32[i];
222	            if (v > 32767) {
223	                v = 32767;
224	            } else if (v < -32768) {
225	                v = -32768;
226	            }
227	            samples[off + i] = (int16_t)v;
228	        }
229	    }
230	}
