312	/* Stream each mono TTS chunk straight into the WAV file on tmpfs,
313	 * duplicating samples to stereo through a small staging buffer.
314	 * The old collect-to-RAM path needed a 2MB PCM buffer PLUS a full
315	 * copy in tmpfs (peak ~3.7MB on long replies) and died with ENOMEM
316	 * (errno=12) → silent reply.  Streaming keeps only ONE copy. */
317	static void tts_file_cb(const unsigned char* pcm, size_t pcm_len,
318	    int is_last, void* ud)
319	{
320	    static int16_t stage[2048];  /* 4KB staging; serialized by speak_lock */
321	    tts_file_ctx_t* ctx = ud;
322	    if (ctx->err) return;
323	    if (pcm && pcm_len > 0) {
324	        if (!s_tts_first_chunk) {
325	            struct timespec now;
326	            clock_gettime(CLOCK_MONOTONIC, &now);
327	            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
328	                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
329	            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
330	            s_tts_first_chunk = 1;
331	        }
332	        const int16_t* mono = (const int16_t*)pcm;
333	        size_t n = pcm_len / sizeof(int16_t);
334	        size_t i = 0;
335	        while (i < n) {
336	            size_t batch = (n - i) > 1024 ? 1024 : (n - i);
337	            for (size_t j = 0; j < batch; j++) {
338	                stage[2 * j]     = mono[i + j];
339	                stage[2 * j + 1] = mono[i + j];
340	            }
341	            ssize_t w = write(ctx->fd, stage,
342	                batch * 2 * sizeof(int16_t));
343	            if (w != (ssize_t)(batch * 2 * sizeof(int16_t))) {
344	                syslog(LOG_ERR,
345	                    "[%s] TTS wav write failed at %zu bytes (errno=%d)\n",
346	                    TAG, ctx->written, errno);
347	                ctx->err = -ENOSPC;
348	                return;
349	            }
350	            ctx->written += batch * 2 * sizeof(int16_t);
351	            i += batch;
352	        }
353	    }
354	    (void)is_last;
355	}
