512	/* ── Frame-level audio capture via NuttX ioctl pipeline ──── */
513	/* Mirrors nxrecorder's internal sequence: RESERVE→GETCAPS→CONFIGURE
514	 * →ALLOCBUFFER×N→REGISTERMQ→ENQUEUEBUFFER×N→START→mq_receive loop */
515	
516	static int capture_open(void)
517	{
518	    /* O_RDWR required — audio driver ioctl needs write permission */
519	    int fd = open(CAPTURE_DEVICE, O_RDWR | O_CLOEXEC);
520	    if (fd < 0) {

882	static void* conversation_thread(void* arg)
883	{
884	    (void)arg;
885	    char asr_text[512];
886	    #define MONO_BUF_MAX 4096  /* enough for 8192-byte stereo → 4096 mono */
887	    uint8_t* mono_buf = malloc(MONO_BUF_MAX);
888	    if (!mono_buf) { return NULL; }
889	    time_t last_speech_time = 0;
890	    syslog(LOG_INFO, "[%s] conversation started\n", TAG);
891	
892	    while (s_voice.conv_running && s_voice.state == VOICE_LISTENING) {
893	
894	        /* 180s idle → re-enable wake gate + notify launcher */
895	        if (!s_voice.wake_gated && last_speech_time > 0
896	            && time(NULL) - last_speech_time > 180) {
897	            s_voice.wake_gated = true;
898	            syslog(LOG_INFO, "[%s] 180s idle, wake gate re-enabled\n", TAG);
899	            if (s_voice.idle_timeout_notify) {
900	                s_voice.idle_timeout_notify();
901	            }
902	        }
903	
904	        /* Re-open capture device if previous iteration closed it.
905	         * After AUDIOIOC_STOP, the NuttX audio upper layer enters
906	         * DRAINING/OPEN state and silently ignores subsequent
907	         * AUDIOIOC_START (lower->ops->start is never called).
908	         * The only reliable fix is to close and re-open the device,
909	         * which resets the upper layer state to PREPARED. */
910	        /* Process deferred mic mute request from button handler.
911	         * I2C writes to ES7210 must happen when the audio driver is
912	         * idle (cap_fd == -1), otherwise LVGL-timer → I2C races with
913	         * audio-driver → I2C and deadlocks the bus. */
914	        if (s_voice.mic_mute_pending) {
915	            s_voice.mic_mute_pending = false;
916	            es7210_set_mic_mute(s_voice.mic_mute_target);
917	            syslog(LOG_INFO, "[%s] mic mute applied: %d\n",
918	                TAG, s_voice.mic_mute_target);
919	        }
920	
921	        /* When mic is muted by user (HW) or preset audio is playing:
922	         * pause capture→ASR cycle.  Audio playing through the speaker
923	         * would be picked up by the mic (echo loop), and the HW mute
924	         * keeps the sleepy face. */
925	        if (s_voice.mic_mute_target
926	#ifdef CONFIG_AI_AGENT_EMOTION_TOY
927	            || tool_emotion_audio_is_playing()
928	#endif
929	            ) {
930	            sleep(1);
931	            continue;
932	        }
933	
934	        if (s_voice.cap_fd < 0) {
935	            s_voice.cap_fd = capture_open();
936	            if (s_voice.cap_fd < 0) {
937	                syslog(LOG_ERR, "[%s] capture re-open failed: %d\n",
938	                    TAG, s_voice.cap_fd);
939	                sleep(1);
940	                continue;
941	            }
942	            syslog(LOG_INFO, "[%s] capture re-opened: %d buffers\n",
943	                TAG, s_voice.cap_nbufs);
944	        }
945	
946	        /* 1. Start capture FIRST to avoid missing audio during ASR
947	         *    TLS handshake (~1-2s). Audio buffers queue up in the
948	         *    driver while we open the ASR stream. */
949	        capture_drain();
950	        capture_start(s_voice.cap_fd);
951	        VOICE_DBG("capture started, opening ASR...");
952	
953	        /* Open ASR stream (blocking TLS + WS handshake).
954	         * Prefer pre_stream if available (pre-opened during TTS). */
955	        voice_asr_stream_t* stream = s_voice.pre_stream;
956	        s_voice.pre_stream = NULL;
957	        if (!stream) {
958	            stream = voice_asr_stream_open();
959	        }
960	
961	        /* Count consecutive ASR open failures as a connectivity proxy.
962	         * network_is_connected() is unreliable — WiFi keeps its IP
963	         * even when internet is unreachable.  3 failures → alert. */
964	        static int s_asr_fail_count = 0;
965	
966	        if (stream) {
967	            VOICE_DBG("ASR stream ready");
968	            s_asr_fail_count = 0;   /* reset on success */
969	        } else {
970	            s_asr_fail_count++;
971	            syslog(LOG_WARNING, "[%s] ASR open failed (%d consecutive)\n",
972	                TAG, s_asr_fail_count);
