977	            }
978	            VOICE_DBG("ASR open failed, retry in 2s");
979	            capture_stop(s_voice.cap_fd);
980	            sleep(2);
981	            continue;
982	        }
983	
984	        asr_text[0] = '\0';
985	        bool got_final = false;
986	
987	        /* Skip the very first frame after cold boot (ADC power-on spike). */
988	        static bool s_first_utterance = true;
989	
990	        time_t start = time(NULL);
991	        int frame_count = 0;
992	        VOICE_DBG("capture started (drain done), listening...");
993	#ifdef CONFIG_EXAMPLES_CONTEST2026_WATCH_BOOT
994	        watch_expression_page_set_face("listening", 0);
995	#endif
