997	        /* Stream ALL audio to server — no client-side VAD.
998	         * The Volcengine ASR server does its own ML-based endpoint
999	         * detection and returns final results via try_recv. */
1000	        while (s_voice.conv_running && s_voice.state == VOICE_LISTENING
1001	               && !got_final && !s_voice.mic_mute_target) {
1002	            struct ap_buffer_s* apb = NULL;
1003	            const uint8_t* pcm = NULL;
1004	            size_t pcm_len = 0;
1005	
1006	            int n = capture_read_frame(&apb, &pcm, &pcm_len);
1007	            if (n == -ETIMEDOUT) {
1008	                VOICE_DBG("timeout after %d frames", frame_count);
1009	                break;
1010	            }
1011	            if (n < 0) { VOICE_DBG("capture_read err=%d at frame %d", n, frame_count); break; }
1012	
1013	            /* Skip ADC power-on spike on very first frame only */
1014	            if (s_first_utterance) {
1015	                s_first_utterance = false;
1016	                capture_release_frame(apb);
1017	                continue;
1018	            }
1019	
1020	            /* Downmix stereo → mono */
1021	            size_t mono_len = downmix_stereo_to_mono(pcm, pcm_len,
1022	                mono_buf, MONO_BUF_MAX);
1023	
1024	            /* Send frame to ASR — server VAD decides speech/noise */
1025	            int sret = voice_asr_stream_send(stream, mono_buf, mono_len);
1026	            capture_release_frame(apb);
1027	            frame_count++;
1028	
1029	            if (sret < 0) {
1030	                syslog(LOG_WARNING, "[%s] stream send error: %d, "
1031	                    "restarting stream\n", TAG, sret);
