1186	                            s_voice.pre_stream =
1187	                                voice_asr_stream_open();
1188	                            if (s_voice.pre_stream) {
1189	                                VOICE_DBG("pre-opened ASR stream "
1190	                                    "(~2s before playback end)");
1191	                            }
1192	                        }
1193	                    }
1194	                    usleep(200 * 1000);
1195	                }
1196	            }
1197	            syslog(LOG_INFO, "[%s] TTS complete, state=%s\n",
1198	                TAG, state_name(s_voice.state));
1199	
1200	            /* Defensive: ensure wake gate stays open after a
1201	             * successful conversation turn.  The gate can only
1202	             * be re-enabled by the 180s idle timeout (top of
