1212	                syslog(LOG_WARNING,
1213	                    "[%s] wake gate was re-enabled during TTS, "
1214	                    "resetting for next turn\n", TAG);
1215	                s_voice.wake_gated = false;
1216	            }
1217	
1218	            /* Resume: speaker acoustic coupling gap.
1219	             * If ASR was pre-opened during TTS, shorter gap needed. */
1220	            if (s_voice.conv_running && s_voice.state == VOICE_LISTENING) {
1221	                if (s_voice.pre_stream) {
1222	                    VOICE_DBG("resuming: 100ms gap (ASR pre-opened)");
1223	                    usleep(100 * 1000);
1224	                } else {
1225	                    usleep(400 * 1000);
1226	                }
1227	            }
1228	            /* Let outer loop re-open stream + start capture */
1229	        } else {
1230	            /* No speech detected — stop capture for clean restart */
1231	            VOICE_DBG("no speech, stopping capture");
1232	            capture_stop(s_voice.cap_fd);
1233	        }
1234	
1235	        /* Close capture device to reset upper layer state.
1236	         * After AUDIOIOC_STOP, audio_start() silently ignores
1237	         * AUDIOIOC_START because the state is DRAINING/OPEN.
1238	         * Close+reopen resets to PREPARED, making START work. */
1239	        capture_close(s_voice.cap_fd);
1240	        s_voice.cap_fd = -1;
1241	    }
1242	
1243	    capture_close(s_voice.cap_fd);
1244	    s_voice.cap_fd = -1;
1245	
1246	    pthread_mutex_lock(&s_voice.lock);
1247	    s_voice.state = VOICE_IDLE;
1248	    pthread_mutex_unlock(&s_voice.lock);
1249	
1250	    syslog(LOG_INFO, "[%s] conversation exit\n", TAG);
1251	    free(mono_buf);
1252	    return NULL;
1253	}
