1257	static int voice_start_common(void)
1258	{
1259	    pthread_mutex_lock(&s_voice.lock);
1260	
1261	    /* Already in conversation — treat as "interrupt and restart listening" */
1262	    if (s_voice.state == VOICE_SPEAKING || s_voice.state == VOICE_PROCESSING) {
1263	        syslog(LOG_INFO, "[%s] interrupting TTS, restarting listen\n", TAG);
1264	        s_voice.tts_abort = 1;
1265	        if (s_voice.tts_pb) {
1266	            audio_playback_stop(s_voice.tts_pb);
1267	        }
1268	        s_voice.state = VOICE_LISTENING;
1269	        /* capture_start happens in conversation_thread outer loop */
1270	        pthread_mutex_unlock(&s_voice.lock);
1271	        syslog(LOG_INFO, "[%s] listening...\n", TAG);
1272	        return 0;
1273	    }
1274	
1275	    if (s_voice.state != VOICE_IDLE) {
1276	        pthread_mutex_unlock(&s_voice.lock);
1277	        syslog(LOG_WARNING, "[%s] already active (state=%d)\n",
1278	            TAG, s_voice.state);
1279	        return -EBUSY;
1280	    }
1281	
1282	    /* Open capture device */
1283	    int fd = capture_open();
1284	    if (fd < 0) {
1285	        pthread_mutex_unlock(&s_voice.lock);
1286	        syslog(LOG_ERR, "[%s] capture open failed: %d\n", TAG, fd);
1287	        return fd;
1288	    }
1289	    s_voice.cap_fd = fd;
1290	
1291	    /* capture_start deferred to conversation_thread —
1292	     * it opens ASR stream first, then starts capture. */
1293	
1294	    s_voice.state = VOICE_LISTENING;
1295	    s_voice.conv_running = true;
1296	    pthread_mutex_unlock(&s_voice.lock);
1297	
1298	    /* Spawn conversation thread */
1299	    pthread_attr_t attr;
1300	    pthread_attr_init(&attr);
1301	    pthread_attr_setstacksize(&attr, CONV_THREAD_STACK);
1302	    int ret = pthread_create(&s_voice.conv_thread, &attr,
1303	        conversation_thread, NULL);
1304	    pthread_attr_destroy(&attr);
1305	
1306	    if (ret != 0) {
1307	        pthread_mutex_lock(&s_voice.lock);
1308	        s_voice.state = VOICE_IDLE;
1309	        s_voice.conv_running = false;
1310	        capture_close(s_voice.cap_fd);
1311	        s_voice.cap_fd = -1;
1312	        pthread_mutex_unlock(&s_voice.lock);
1313	        syslog(LOG_ERR, "[%s] pthread_create failed: %d\n", TAG, ret);
1314	        return -ret;
1315	    }
1316	
1317	    syslog(LOG_INFO, "[%s] listening (voice_stop to exit)\n", TAG);
1318	    return 0;
1319	}
