1453	/* Run the ReAct tool-calling loop. Returns final_text (caller owns). */
1454	static char* run_react_loop(const char* sys_prompt, cJSON* messages,
1455	    const char* tools_json, char* tool_output, size_t tool_size,
1456	    const agent_msg_t* msg)
1457	{
1458	    char prev_sig[512];
1459	    int dup_count;
1460	    char prev_name[64];
1461	    int name_repeat;
1462	    int iteration;
1463	    char* final_text = NULL;
1464	
1465	    /* Clear stale speak text from previous message */
1466	    free(s_speak_text);
1467	    s_speak_text = NULL;
1468	    s_emotion_tool_ran = false;
1469	    s_face_tool_ran = false;
1470	
1471	    prev_sig[0] = '\0';
1472	    dup_count = 0;
1473	    prev_name[0] = '\0';
1474	    name_repeat = 0;
1475	    int last_total_tokens = 0;
1476	    bool watchdog_fired = false;
1477	
1478	    /* Cap max_completion_tokens for TTS-bound channels.  Their system
1479	     * prompt already forces ≤40-character replies, so a small budget
1480	     * both prevents runaway generation and shrinks LLM server-side
1481	     * scheduling latency (large defaults inflate TTFT).  Non-voice
1482	     * channels fall through to the built-in default.  Cleared before
1483	     * every return so the hint never leaks across messages. */
1484	    bool is_short_channel =
1485	        strcmp(msg->channel, AGENT_CHAN_VOICE) == 0
1486	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
1487	        || strcmp(msg->channel, AGENT_CHAN_QUICKAPP) == 0
1488	#endif
1489	        ;
1490	    llm_set_max_tokens_hint(is_short_channel
1491	        ? AGENT_LLM_MAX_TOKENS_VOICE : 0);
1492	    /* Voice replies are capped at ~40 chars — deep thinking on
1493	     * reasoning models (mimo-v2.5-pro) only adds 20s+ latency. */
1494	    llm_set_thinking_disabled_hint(is_short_channel);
1495	
1496	    /* Router: select and apply best backend before first LLM call.
1497	     * Estimate complexity from the last user message. */
1498	    llm_complexity_t complexity = LLM_COMPLEXITY_SIMPLE;
1499	    if (msg->content) {
1500	        complexity = llm_router_estimate_complexity(
1501	            msg->content, strlen(msg->content));
1502	    }
1503	    int router_idx = llm_router_select(complexity);
1504	    if (router_idx >= 0) {
1505	        llm_router_apply(router_idx);
1506	    }
1507	
1508	    /* Structured trace: begin */
1509	    agent_trace_t trace;
1510	    agent_trace_begin(&trace, msg->chat_id, msg->channel);
1511	    trace.backend_idx = router_idx;
1512	
1513	    /* Cache check: for simple queries, try cache before LLM call */
1514	    if (msg->content && complexity == LLM_COMPLEXITY_SIMPLE) {
1515	        char* cached = llm_cache_get(msg->content, strlen(msg->content));
1516	        if (cached) {
1517	            final_text = cached;
1518	            agent_trace_step(&trace, 0, NULL, 0, 1);
1519	            agent_trace_end(&trace, AGENT_TRACE_OK);
1520	            goto send_reply;
1521	        }
1522	    }
1523	
1524	    for (iteration = 0; iteration < AGENT_AI_AGENT_MAX_TOOL_ITER;
1525	         iteration++) {

1931	static void* agent_loop_task(void* arg)
1932	{
1933	    (void)arg;
1934	    agent_mem_status_t mem_st;
1935	
1936	    agent_mem_get_status(&mem_st);
1937	    syslog(LOG_INFO, "[%s] Agent loop started, free heap: %zu\n",
1938	        TAG, mem_st.free_heap);
1939	
1940	    size_t ctx_size = agent_mem_safe_size(
1941	        AGENT_CONTEXT_BUF_SIZE, 4 * 1024);
1942	    size_t hist_size = agent_mem_safe_size(
1943	        AGENT_LLM_STREAM_BUF_SIZE, 8 * 1024);
1944	    size_t tool_size = agent_mem_safe_size(
1945	        TOOL_OUTPUT_SIZE, TOOL_OUTPUT_SIZE_MIN);
1946	
1947	    char* sys_prompt = calloc(1, ctx_size);
1948	    char* history_json = calloc(1, hist_size);
1949	    char* tool_output = calloc(1, tool_size);
1950	
1951	    if (!sys_prompt || !history_json || !tool_output) {
1952	        syslog(LOG_ERR, "[%s] Failed to allocate agent buffers\n", TAG);
1953	        free(sys_prompt);
1954	        free(history_json);
1955	        free(tool_output);
1956	        return NULL;
1957	    }
1958	
1959	    syslog(LOG_INFO, "[%s] Buffers: ctx=%zu hist=%zu tool=%zu\n",
1960	        TAG, ctx_size, hist_size, tool_size);
1961	
1962	    /* Initialize memory pool for parallel tool outputs */
1963	    size_t pool_buf_size = agent_mem_safe_size(
1964	        TOOL_OUTPUT_SIZE_LARGE, TOOL_OUTPUT_SIZE_MIN);
1965	    if (agent_pool_init(&s_tool_pool, pool_buf_size,
1966	            AGENT_MAX_TOOL_CALLS)
1967	        == OK) {
1968	        s_pool_ready = true;
1969	        syslog(LOG_INFO, "[%s] Tool output pool: %d x %zu bytes\n",
1970	            TAG, AGENT_MAX_TOOL_CALLS, pool_buf_size);
1971	    } else {
1972	        syslog(LOG_WARNING,
1973	            "[%s] Pool init failed, using heap fallback\n", TAG);
1974	    }
1975	
1976	    char* tools_json = tool_registry_get_tools_json();
1977	
1978	    syslog(LOG_INFO, "[%s] Tools JSON loaded: %d bytes\n",
1979	        TAG, tools_json ? (int)strlen(tools_json) : 0);
1980	
1981	    while (!agent_shutdown_requested()) {
1982	        agent_msg_t msg;
1983	        int err = message_bus_pop_inbound(&msg, UINT32_MAX);
1984	
1985	        if (err != OK) {
1986	            continue;
1987	        }
1988	
1989	        if (agent_shutdown_requested()) {
1990	            free(msg.content);
1991	            free(msg.image_b64);
1992	            break;
1993	        }
1994	
1995	        syslog(LOG_INFO, "[%s] Processing message from %s:%s\n",
1996	            TAG, msg.channel, msg.chat_id);
1997	
1998	        /* Voice request: pre-open the TTS WebSocket in parallel with
1999	         * the LLM call.  MUST happen here (agent task group) — the
2000	         * conversation thread lives in the launcher task group and
2001	         * NuttX fd tables are per task group, so a socket opened
2002	         * there is unusable by voice_channel_speak() (EBADF). */
2003	        if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
2004	#ifdef CONFIG_AI_AGENT_VOLC_E2E
2005	            /* The E2E backend already owns a persistent connection that
2006	             * carries TTS, so pre-warming a second TLS context (~25KB)
2007	             * plus a worker thread would be pure waste. */
2008	            const char* tts_be = voice_tts_get_backend();
2009	            if (!tts_be || strcmp(tts_be, AGENT_VOICE_BACKEND_E2E) != 0)
2010	#endif
2011	            {
2012	                tts_preopen_spawn();
2013	            }
2014	        }
2015	
2016	        /* Check memory pressure */
2017	        agent_mem_get_status(&mem_st);
2018	        if (mem_st.free_heap < AGENT_MEM_RESERVE_BYTES) {
2019	            syslog(LOG_WARNING,
2020	                "[%s] Low memory: %zu bytes free, skipping\n",
2021	                TAG, mem_st.free_heap);
2022	            agent_msg_t out = { 0 };
2023	            strncpy(out.channel, msg.channel,
2024	                sizeof(out.channel) - 1);
2025	            strncpy(out.chat_id, msg.chat_id,
2026	                sizeof(out.chat_id) - 1);
2027	            out.content = strdup("系统内存不足，请稍后再试。");
2028	            if (out.content) {
2029	                if (message_bus_push_outbound(&out) != OK) {
2030	                    free(out.content);
2031	                }
2032	            }
2033	            free(msg.content);
2034	            continue;
2035	        }
2036	
2037	        /* Slash commands — fast path, bypass LLM */
2038	        char* reply = handle_slash_command(&msg);
2039	
2040	        /* Prompt injection check — before LLM */
2041	        if (!reply && tool_guard_check_injection(msg.content)) {
2042	            syslog(LOG_WARNING,
2043	                "[%s] Prompt injection blocked from %s:%s\n",
2044	                TAG, msg.channel, msg.chat_id);
2045	            reply = strdup("I can't do that.");
2046	            if (!reply) {
2047	                /* Fail-closed: skip this message entirely */
2048	                free(msg.content);
2049	                continue;
2050	            }
2051	        }
2052	
2053	        /* NL fast path — after injection check, before LLM */
2054	        if (!reply) {
2055	            reply = handle_nl_fast_path(msg.content);
2056	        }
2057	
2058	        if (reply) {
2059	            /* Voice-first: speak fast-path response */
2060	            voice_channel_speak(reply);
2061	
2062	            agent_msg_t out = { 0 };
2063	            strncpy(out.channel, msg.channel,
2064	                sizeof(out.channel) - 1);
2065	            strncpy(out.chat_id, msg.chat_id,
2066	                sizeof(out.chat_id) - 1);
2067	            out.content = reply;
2068	            if (message_bus_push_outbound(&out) != OK) {
2069	                free(reply);
2070	            }
2071	            free(msg.content);
2072	            continue;
2073	        }
2074	
2075	        /* Hot-reload skills if directory changed */
2076	        if (skill_loader_check_changed()) {
2077	            syslog(LOG_INFO, "[%s] Skills changed, refreshing\n", TAG);
2078	            skill_loader_refresh();
2079	        }
2080	
2081	        context_build_system_prompt(sys_prompt, ctx_size);
2082	        inject_session_context(sys_prompt, ctx_size,
2083	            msg.channel, msg.chat_id);
2084	
2085	        /* Refresh tools JSON — Node tools are dynamic */
2086	        free(tools_json);
2087	        tools_json = tool_registry_get_tools_json();
2088	
2089	        /* Decide whether this message needs tools at all.
2090	         * Chitchat like "你好"/"你在干嘛" gets tools_json=NULL,
2091	         * dropping ~7KB from the LLM request body. */
2092	        const char* llm_tools = msg_needs_tools(msg.content)
2093	            ? tools_json : NULL;
2094	        if (!llm_tools) {
2095	            syslog(LOG_INFO,
2096	                "[%s] trivial chat, skipping tools (fast=%d llm=%d)\n",
2097	                TAG, s_fast_path_count, s_llm_path_count);
2098	        }
2099	
2100	        /* Pre-inject matching skill content into system prompt.
2101	         * When user says "压力好大", stress-relief content is
2102	         * appended so LLM sees full steps without read_file.
2103	         * The directive header is essential: the Skills summary
2104	         * advertises "(read with: read_file ...)" and without an
2105	         * explicit override the LLM burns a whole extra round
2106	         * (~10s) re-reading the skill file it already has. */
2107	        bool has_skill = false;
2108	        if (llm_tools && msg.content) {
2109	            char* skill = skill_loader_match_trigger(msg.content);
2110	            if (skill) {
2111	                has_skill = true;
2112	                static const char kSkillHdr[] =
2113	                    "\n## 已命中技能（全文已内联如下）\n"
2114	                    "禁止再用 read_file 读任何 skill 文件；"
2115	                    "直接在本轮按 How to use 步骤在同一个 "
2116	                    "tool_calls 数组里一次性完成全部工具调用。\n";
2117	                size_t prompt_len = strlen(sys_prompt);
2118	                size_t hdr_len    = sizeof(kSkillHdr) - 1;
2119	                size_t skill_len  = strlen(skill);
2120	                if (prompt_len + hdr_len + skill_len + 1 < ctx_size) {
2121	                    memcpy(sys_prompt + prompt_len, kSkillHdr, hdr_len);
2122	                    memcpy(sys_prompt + prompt_len + hdr_len,
2123	                           skill, skill_len + 1);
2124	                    syslog(LOG_INFO,
2125	                        "[%s] skill content injected "
2126	                        "(prompt %zu→%zu bytes)\n",
2127	                        TAG, prompt_len,
2128	                        strlen(sys_prompt));
2129	                }
2130	                free(skill);
2131	            }
2132	        }
2133	
2134	        /* Emotion hint: when no skill matched, scan user text for emotion
2135	         * keywords and inject a strong directive so the LLM calls set_face
2136	         * reliably.  Skill messages skip this — the skill itself specifies
2137	         * the face. */
2138	        char* emotion_hint = NULL;
2139	        if (!has_skill && llm_tools && msg.content) {
2140	            int hint_count = 0;
2141	            emotion_hint = build_emotion_hint(msg.content, &hint_count);
2142	            if (emotion_hint) {
2143	                syslog(LOG_INFO, "[%s] emotion hint injected (%d triggers)\n",
2144	                    TAG, hint_count);
2145	            }
2146	        }
2147	
2148	        cJSON* messages = build_messages(msg.chat_id, msg.content,
2149	            history_json, hist_size);
2150	
2151	        /* Emotion hint: insert as system message right before user msg.
2152	         * build_messages appends the user msg at the end, so we detach it,
2153	         * add the hint, then re-append the user msg. */
