483	{
484	    if (!ctx || ctx->net.fd < 0) return -EINVAL;
485	
486	    pthread_mutex_lock(&s_tls_lock);
487	    size_t written = 0;
488	    while (written < len) {
489	        int ret = mbedtls_ssl_write(&ctx->ssl, buf + written, len - written);
490	        if (ret > 0) {
491	            written += (size_t)ret;
492	        } else if (ret == MBEDTLS_ERR_SSL_WANT_WRITE
493	            || ret == MBEDTLS_ERR_SSL_WANT_READ) {
494	            pthread_mutex_unlock(&s_tls_lock);
495	            usleep(1000);
496	            pthread_mutex_lock(&s_tls_lock);
