501	        } else {
502	            pthread_mutex_unlock(&s_tls_lock);
503	            syslog(LOG_ERR, "[%s] ssl_write: -0x%04x\n", TAG, -ret);
504	            return -EIO;
505	        }
506	    }
507	    pthread_mutex_unlock(&s_tls_lock);
